import type Phaser from 'phaser';
import type { PlayerAppearance } from '../../core/art/artMap.ts';
import { findRow, frameAt, resolveDirection, resolveFrame, rowDuration } from '../../core/art/spriteSheets.ts';
import type { Combatant } from '../../core/combat/combatant.ts';
import type { Equipment } from '../../core/items/equipment.ts';
import { cellToScreen, type IsoMetrics } from '../../core/math/iso.ts';
import type { MotionState } from '../../core/movement/characterMotion.ts';
import { DIRECTIONS, type Direction } from '../../core/movement/direction.ts';
import { SHADOW_TEXTURE, type ArtAssets, type ArtLayer } from '../rendering/artAssets.ts';
import { ENTITY_DEPTH_BIAS, sortedDepth } from '../rendering/depth.ts';
import { PLAYER_ORIGIN_Y, PLAYER_TEXTURE } from '../rendering/placeholderTextures.ts';
import { applyCombatVisuals } from './combatVisuals.ts';

const HURT_FLASH = 0.1;
/** Tiempo que se muestra el fotograma de daño. */
const HURT_POSE = 0.14;

/** Capa del muñeco articulado (cuerpo, casco o arma) con su desplazamiento de profundidad. */
interface DollLayer {
  readonly sprite: Phaser.GameObjects.Sprite;
  readonly layer: ArtLayer;
  readonly bias: number;
}

interface Pose {
  readonly animation: string;
  /** Segundos transcurridos desde que empezó la animación (las cíclicas usan el tiempo global). */
  readonly elapsed: number;
  readonly facing: Direction;
}

/**
 * Representación gráfica del jugador. Solo refleja el estado; no contiene reglas.
 * Con el arte del Nivel A es un muñeco articulado (ART_SPEC §3): cuerpo base (con la paleta del torso
 * equipado), casco y arma como capas sincronizadas por fotograma; sin arte, usa el placeholder animado.
 */
export class PlayerView {
  /** Cuerpo: la cámara lo sigue. */
  readonly sprite: Phaser.GameObjects.Sprite;
  private readonly scene: Phaser.Scene;
  private readonly art: ArtAssets;
  private readonly appearance: PlayerAppearance;
  private readonly barrier: Phaser.GameObjects.Graphics;
  private readonly shadow: Phaser.GameObjects.Image | null;
  private readonly iso: IsoMetrics;
  private body: ArtLayer | null;
  private helmet: DollLayer | null = null;
  private weapon: DollLayer | null = null;
  private hurtFlashUntil = 0;
  private hurtUntil = 0;
  private deathStart: number | null = null;
  /** Acción en curso (ataque, giro o lanzamiento) que tiene prioridad sobre caminar o estar quieto. */
  private action: { readonly kind: string; readonly until: number; readonly start: number } | null = null;
  /** Una acción nueva reinicia su animación aunque sea la misma que la anterior (golpes seguidos). */
  private restart = false;

  constructor(scene: Phaser.Scene, state: MotionState, iso: IsoMetrics, art: ArtAssets, appearance: PlayerAppearance) {
    this.scene = scene;
    this.iso = iso;
    this.art = art;
    this.appearance = appearance;
    this.body = art.playerBody(scene, appearance, null);
    if (this.body) {
      const { origin } = this.body.sheet;
      this.sprite = scene.add.sprite(0, 0, this.body.key, 0).setOrigin(origin.x, origin.y);
      this.shadow = scene.add.image(0, 0, SHADOW_TEXTURE).setOrigin(0.5, 0.5).setScale(0.75, 0.6);
    } else {
      this.sprite = scene.add.sprite(0, 0, PLAYER_TEXTURE, 0).setOrigin(0.5, PLAYER_ORIGIN_Y);
      this.shadow = null;
    }
    this.barrier = scene.add.graphics();
    const p = cellToScreen(state.position, iso);
    this.sprite.setPosition(p.x, p.y);
  }

  /** Actualiza las capas de equipo (y la paleta del cuerpo) según lo equipado. */
  setEquipment(equipment: Equipment): void {
    if (!this.body) return;
    const body = this.art.playerBody(this.scene, this.appearance, equipment.get('chest'));
    if (body && body.key !== this.body.key) {
      this.body = body;
      this.sprite.setTexture(body.key, 0);
    }
    this.helmet = this.setLayer(this.helmet, this.art.equipment(equipment.get('head')), 0.01);
    this.weapon = this.setLayer(this.weapon, this.art.equipment(equipment.get('weapon')), 0.02);
  }

  private setLayer(current: DollLayer | null, layer: ArtLayer | null, bias: number): DollLayer | null {
    if (!layer) {
      current?.sprite.destroy();
      return null;
    }
    if (current && current.layer.key === layer.key) return current;
    current?.sprite.destroy();
    const sprite = this.scene.add.sprite(0, 0, layer.key, 0).setOrigin(layer.sheet.origin.x, layer.sheet.origin.y);
    return { sprite, layer, bias };
  }

  hurt(time: number): void {
    this.hurtFlashUntil = time + HURT_FLASH;
    this.hurtUntil = time + HURT_POSE;
  }

  /** Claves de textura de las capas visibles (cuerpo, casco, arma), para depuración y pruebas. */
  layerKeys(): string[] {
    const layers = [this.sprite, this.helmet?.sprite, this.weapon?.sprite];
    return layers.flatMap((s) => (s?.visible ? [s.texture.key] : []));
  }

  /**
   * Reproduce la animación de una habilidad (campo `animation` de los datos): attack, spin, cast o dash.
   * `duration` es el tiempo que el personaje queda ocupado.
   */
  act(animation: string, time: number, duration: number): void {
    this.action = { kind: animation, start: time, until: time + Math.max(0.2, duration) };
    this.restart = true;
  }

  sync(state: MotionState, combatant: Combatant, time: number): void {
    const p = cellToScreen(state.position, this.iso);
    const depth = sortedDepth(p.y) + ENTITY_DEPTH_BIAS;
    if (this.body) this.syncDoll(this.body, state, combatant, time, p, depth);
    else this.syncPlaceholder(state, combatant, time, p, depth);

    // Barrera de "Protección del Bosque".
    this.barrier.clear();
    if (combatant.alive && combatant.statuses.has('protection')) {
      const pulse = 0.55 + Math.sin(time * 6) * 0.15;
      this.barrier.setDepth(depth + 0.1);
      this.barrier.lineStyle(2, 0x7fd3ff, pulse).strokeEllipse(p.x, p.y - 24, 44, 56);
      this.barrier.fillStyle(0x7fd3ff, 0.12).fillEllipse(p.x, p.y - 24, 44, 56);
    }
  }

  /** Elige la animación y su fase según el estado (muerte > daño > acción > caminar > reposo). */
  private pose(state: MotionState, alive: boolean, time: number): Pose {
    if (!alive) return { animation: 'death', elapsed: time - (this.deathStart ?? time), facing: state.facing };
    if (time < this.hurtUntil) return { animation: 'hurt', elapsed: 0, facing: state.facing };
    const a = this.action && time < this.action.until ? this.action : null;
    if (a) {
      const elapsed = time - a.start;
      switch (a.kind) {
        case 'attack':
          return { animation: 'attack', elapsed, facing: state.facing };
        case 'spin': {
          // Corte Circular: gira por las ocho orientaciones repitiendo el golpe.
          const i = (DIRECTIONS.indexOf(state.facing) + Math.floor(elapsed * 32)) % DIRECTIONS.length;
          return { animation: 'attack', elapsed: elapsed % 0.3, facing: DIRECTIONS[i] as Direction };
        }
        case 'cast':
          return { animation: 'cast', elapsed, facing: state.facing };
        case 'dash':
          return { animation: 'dash', elapsed, facing: state.facing };
        default:
          break;
      }
    }
    return { animation: state.moving ? 'walk' : 'idle', elapsed: time, facing: state.facing };
  }

  private syncDoll(body: ArtLayer, state: MotionState, combatant: Combatant, time: number, p: { x: number; y: number }, depth: number): void {
    if (!combatant.alive) this.deathStart ??= time;
    else this.deathStart = null;
    const pose = this.pose(state, combatant.alive, time);
    this.restart = false;
    // Todas las capas comparten la fase de la fila del cuerpo para no desfasarse (ART_SPEC §3).
    const bodyRow = findRow(body.sheet, pose.animation, resolveDirection(body.sheet, pose.facing).direction);
    const frame = bodyRow ? frameAt(bodyRow, pose.elapsed) : 0;
    const layers: DollLayer[] = [{ sprite: this.sprite, layer: body, bias: 0 }];
    if (this.helmet) layers.push(this.helmet);
    if (this.weapon) layers.push(this.weapon);
    for (const { sprite, layer, bias } of layers) {
      const r = resolveFrame(layer.sheet, pose.animation, pose.facing, frame);
      if (!r) {
        sprite.setVisible(false);
        continue;
      }
      sprite.setFrame(r.index).setFlipX(r.flipX).setPosition(p.x, p.y).setDepth(depth + bias).setVisible(true);
      applyCombatVisuals(sprite, combatant, time, this.hurtFlashUntil, 0);
    }
    const lying = !combatant.alive && bodyRow !== null && pose.elapsed >= rowDuration(bodyRow);
    this.shadow?.setPosition(p.x, p.y - 1).setDepth(depth - 0.05).setVisible(!lying);
  }

  private syncPlaceholder(state: MotionState, combatant: Combatant, time: number, p: { x: number; y: number }, depth: number): void {
    this.sprite.setPosition(p.x, p.y).setDepth(depth).setVisible(combatant.alive);
    const anim = this.placeholderAnim(state, time);
    if (this.restart || this.sprite.anims.currentAnim?.key !== anim) this.sprite.play(anim, !this.restart);
    this.restart = false;
    this.sprite.anims.timeScale = this.action?.kind === 'dash' && time < this.action.until ? 2.5 : 1;
    applyCombatVisuals(this.sprite, combatant, time, this.hurtFlashUntil, 0);
  }

  private placeholderAnim(state: MotionState, time: number): string {
    const a = this.action && time < this.action.until ? this.action : null;
    if (!a) return `player-${state.moving ? 'walk' : 'idle'}-${state.facing}`;
    switch (a.kind) {
      case 'attack':
        return `player-attack-${state.facing}`;
      case 'spin': {
        const i = (DIRECTIONS.indexOf(state.facing) + Math.floor((time - a.start) * 32)) % DIRECTIONS.length;
        return `player-attack-${DIRECTIONS[i] as Direction}`;
      }
      case 'cast':
        return `player-cast-${state.facing}`;
      default:
        return `player-walk-${state.facing}`;
    }
  }
}
