import { normalize, type Vec2 } from '../math/vector.ts';

export interface JoystickState {
  /** Dirección en pantalla, longitud 0 o 1. */
  readonly vector: Vec2;
  /** Posición de la palanca (recortada al radio de la base). */
  readonly knob: Vec2;
  /** true si el dedo está fuera de la zona muerta. */
  readonly active: boolean;
}

/**
 * Estado de un joystick virtual a partir del centro de la base y la posición del dedo.
 * `deadZone` es la fracción del radio sin efecto (evita derivas con el dedo quieto).
 */
export function joystickState(center: Vec2, finger: Vec2, radius: number, deadZone: number): JoystickState {
  const dx = finger.x - center.x;
  const dy = finger.y - center.y;
  const dist = Math.hypot(dx, dy);
  if (dist <= radius * deadZone) return { vector: { x: 0, y: 0 }, knob: center, active: false };
  const vector = normalize({ x: dx, y: dy });
  const k = Math.min(dist, radius);
  return { vector, knob: { x: center.x + vector.x * k, y: center.y + vector.y * k }, active: true };
}
