import Phaser from 'phaser';
import { artReferencesFrom } from '../../core/art/artContent.ts';
import { parseArtMap, validateArtMap } from '../../core/art/artMap.ts';
import { parsePaletteCatalog } from '../../core/art/palette.ts';
import { parseSheetCatalog } from '../../core/art/spriteSheets.ts';
import { DataValidationError } from '../../core/data/validate.ts';
import contentMapJson from '../../data/art/content-map.json';
import palettesJson from '../../data/art/palettes.json';
import sheetsJson from '../../data/art/sheets.json';
import { loadContent, type GameContent } from '../content.ts';
import { ArtAssets, REGISTRY_ART } from '../rendering/artAssets.ts';
import {
  createCreatureTextures,
  createPlaceholderTextures,
  createNarrativeTextures,
  createPlantTextures,
  createPlayerAnimations,
} from '../rendering/placeholderTextures.ts';
import { createItemIcons } from '../rendering/itemIcons.ts';
import { defaultSettings, REGISTRY_SETTINGS } from '../input/settings.ts';
import { REGISTRY_CONTENT, SceneKeys } from './keys.ts';

/**
 * Valida el contenido, carga el arte del Nivel A (`public/art`) y prepara los recursos compartidos.
 * Las hojas que falten se sustituyen por los placeholders generados por código. Si los datos son
 * inválidos, lo muestra en pantalla.
 */
export class BootScene extends Phaser.Scene {
  private content: GameContent | null = null;
  private art: ArtAssets | null = null;

  constructor() {
    super(SceneKeys.Boot);
  }

  preload(): void {
    try {
      const content = loadContent();
      const art = loadArt(content);
      this.content = content;
      this.art = art;
      this.registry.set(REGISTRY_CONTENT, content);
      this.registry.set(REGISTRY_SETTINGS, defaultSettings(content.controlsRaw));
      this.registry.set(REGISTRY_ART, art);
      const label = this.add.text(this.scale.width / 2, this.scale.height / 2, 'Cargando…', { fontFamily: 'monospace', fontSize: '16px', color: '#c9c3b0' }).setOrigin(0.5);
      this.load.on(Phaser.Loader.Events.PROGRESS, (value: number) => { label.setText(`Cargando… ${Math.round(value * 100)} %`); });
      this.load.on(Phaser.Loader.Events.FILE_LOAD_ERROR, (file: Phaser.Loader.File) => { console.warn(`No se pudo cargar ${file.key} (${file.url as string})`); });
      art.queue(this.load);
    } catch (error: unknown) {
      this.showError(error);
    }
  }

  create(): void {
    const content = this.content;
    const art = this.art;
    if (!content || !art) return;
    try {
      art.finish(this);
      const missing = art.debug().missing;
      if (missing.length > 0) console.warn(`Arte no disponible (se usan placeholders): ${missing.join(', ')}`);
      createPlaceholderTextures(this, content.catalog);
      createPlayerAnimations(this);
      createCreatureTextures(this, [...content.creatures.all.values()].map((c) => c.spriteAtlas));
      createItemIcons(this, content.items);
      createNarrativeTextures(this, [...content.narrative.npcs.values()].map((n) => n.spriteAtlas));
      createPlantTextures(
        this,
        [...content.plants.all.values()].map((p) => ({ id: p.id, ...content.items.get(p.itemId).icon })),
      );
      this.scene.start(SceneKeys.Menu);
    } catch (error: unknown) {
      this.showError(error);
    }
  }

  private showError(error: unknown): void {
    const message = error instanceof Error ? error.message : String(error);
    console.error(error);
    this.add
      .text(16, 16, `Error al cargar el contenido:\n\n${message}`, {
        fontFamily: 'monospace',
        fontSize: '14px',
        color: '#ff8080',
        wordWrap: { width: this.scale.width - 32 },
      })
      .setName('boot-error');
  }
}

/** Catálogo de hojas, paletas y correspondencia con el contenido, validados entre sí. */
function loadArt(content: GameContent): ArtAssets {
  const sheets = parseSheetCatalog(sheetsJson, 'data/art/sheets.json');
  const palettes = parsePaletteCatalog(palettesJson, 'data/art/palettes.json');
  const map = parseArtMap(contentMapJson, 'data/art/content-map.json');
  const problems = validateArtMap(map, sheets, artReferencesFrom(content, content.catalog, palettes));
  if (problems.length > 0) throw new DataValidationError('data/art/content-map.json', problems);
  return new ArtAssets(sheets, map, palettes);
}
