import Phaser from 'phaser';
import { AlchemyScene } from '../game/scenes/AlchemyScene.ts';
import { BootScene } from '../game/scenes/BootScene.ts';
import { CharacterScene } from '../game/scenes/CharacterScene.ts';
import { DialogueScene } from '../game/scenes/DialogueScene.ts';
import { JournalScene } from '../game/scenes/JournalScene.ts';
import { PauseScene } from '../game/scenes/PauseScene.ts';
import { GameScene } from '../game/scenes/GameScene.ts';
import { HudScene } from '../game/scenes/HudScene.ts';
import { InventoryScene } from '../game/scenes/InventoryScene.ts';
import { MapScene } from '../game/scenes/MapScene.ts';
import { MenuScene } from '../game/scenes/MenuScene.ts';
import { OptionsScene } from '../game/scenes/OptionsScene.ts';

export function createGameConfig(parent: string): Phaser.Types.Core.GameConfig {
  return {
    type: Phaser.AUTO,
    parent,
    backgroundColor: '#0d0f14',
    pixelArt: true,
    roundPixels: true,
    scale: {
      mode: Phaser.Scale.RESIZE,
      width: 1280,
      height: 720,
    },
    fps: { target: 60 },
    // Joystick y botones táctiles a la vez (el valor predeterminado solo admite dos punteros).
    input: { activePointers: 4 },
    scene: [BootScene, MenuScene, CharacterScene, GameScene, HudScene, InventoryScene, AlchemyScene, DialogueScene, JournalScene, PauseScene, MapScene, OptionsScene],
  };
}
