import { HEX_COLOR_PATTERN, Issues } from '../data/validate.ts';

/** Tablas de sustitución exacta de color (RGB) para los conjuntos de armadura (ART_SPEC §3). */
export type PaletteSwap = Readonly<Record<string, string>>;

export interface PaletteCatalog {
  readonly all: ReadonlyMap<string, PaletteSwap>;
  get(id: string): PaletteSwap;
  has(id: string): boolean;
}

/** Lee `palettes.json`: `{ "<id>": { "#origen": "#destino", … }, "status": "…" }`. */
export function parsePaletteCatalog(raw: unknown, source = 'data/art/palettes.json'): PaletteCatalog {
  const issues = new Issues();
  const root = issues.record(raw, '$');
  const all = new Map<string, PaletteSwap>();
  if (root) {
    for (const [id, value] of Object.entries(root)) {
      if (typeof value === 'string') continue; // notas y estado
      const table = issues.record(value, `$.${id}`);
      if (!table) continue;
      const swap: Record<string, string> = {};
      for (const [from, to] of Object.entries(table)) {
        if (!HEX_COLOR_PATTERN.test(from)) issues.add(`$.${id}.${from}`, 'color de origen inválido');
        const dest = issues.string(to, `$.${id}.${from}`, { pattern: HEX_COLOR_PATTERN });
        if (dest) swap[from.toLowerCase()] = dest.toLowerCase();
      }
      all.set(id, swap);
    }
  }
  issues.throwIfAny(source);
  return {
    all,
    get: (id) => {
      const p = all.get(id);
      if (!p) throw new Error(`Paleta desconocida: "${id}"`);
      return p;
    },
    has: (id) => all.has(id),
  };
}

function hexToRgb(hex: string): readonly [number, number, number] {
  const n = parseInt(hex.slice(1), 16);
  return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
}

/**
 * Sustituye en un búfer RGBA los colores exactos de la tabla, conservando el alfa y sin tocar el resto
 * (piel, pelo, contorno). Devuelve cuántos píxeles cambiaron.
 */
export function swapPaletteInPlace(pixels: Uint8ClampedArray, swap: PaletteSwap): number {
  const table = new Map<number, readonly [number, number, number]>();
  for (const [from, to] of Object.entries(swap)) {
    const [r, g, b] = hexToRgb(from);
    table.set((r << 16) | (g << 8) | b, hexToRgb(to));
  }
  let changed = 0;
  for (let i = 0; i + 3 < pixels.length; i += 4) {
    if (pixels[i + 3] === 0) continue;
    const key = ((pixels[i] ?? 0) << 16) | ((pixels[i + 1] ?? 0) << 8) | (pixels[i + 2] ?? 0);
    const to = table.get(key);
    if (!to) continue;
    pixels[i] = to[0];
    pixels[i + 1] = to[1];
    pixels[i + 2] = to[2];
    changed++;
  }
  return changed;
}
