import { HEX_COLOR_PATTERN, ID_PATTERN, Issues } from '../data/validate.ts';

/** Roles de las profesiones (lámina «Profesiones oficiales»; estilos funcionales de GAME_DESIGN §5). */
export const PROFESSION_ROLES = ['guerrero', 'tanque', 'asesino', 'tirador', 'mago', 'apoyo'] as const;
export type ProfessionRole = (typeof PROFESSION_ROLES)[number];

export const ROLE_NAMES: Readonly<Record<ProfessionRole, string>> = {
  guerrero: 'Guerrero',
  tanque: 'Tanque',
  asesino: 'Asesino',
  tirador: 'Tirador',
  mago: 'Mago',
  apoyo: 'Apoyo',
};

/** Civilización jugable (GAME_DESIGN §2: facción cultural, no categoría biológica). */
export interface CivilizationDefinition {
  readonly id: string;
  readonly name: string;
  readonly tagline: string;
  readonly region: string;
  readonly colors: { readonly primary: string; readonly secondary: string };
  /** Ids de sus profesiones, en el orden de la lámina. */
  readonly professions: readonly string[];
}

/** Entrada del catálogo de profesiones; las jugables tienen además su ProfessionDefinition completa. */
export interface ProfessionEntry {
  readonly id: string;
  readonly civilizationId: string;
  readonly name: string;
  readonly role: ProfessionRole;
  readonly finalAbility: string;
  readonly playable: boolean;
}

export interface CivilizationCatalog {
  readonly civilizations: ReadonlyMap<string, CivilizationDefinition>;
  readonly professions: ReadonlyMap<string, ProfessionEntry>;
  civilization(id: string): CivilizationDefinition;
  profession(id: string): ProfessionEntry;
  /** Profesiones de una civilización, en orden. */
  professionsOf(civilizationId: string): ProfessionEntry[];
}

export const PROFESSIONS_PER_CIVILIZATION = 5;

/** Valida civilizaciones y catálogo de profesiones y sus referencias cruzadas. */
export function parseCivilizationCatalog(civRaw: unknown, profRaw: unknown, source: string): CivilizationCatalog {
  const issues = new Issues();
  const professions = new Map<string, ProfessionEntry>();
  issues.array(issues.record(profRaw, '$professions')?.['professions'], '$professions.professions')?.forEach((entry, i) => {
    const p = `$professions.professions[${i}]`;
    const r = issues.record(entry, p);
    if (!r) return;
    const before = issues.count;
    const def = {
      id: issues.string(r['id'], `${p}.id`, { pattern: ID_PATTERN }),
      civilizationId: issues.string(r['civilizationId'], `${p}.civilizationId`, { pattern: ID_PATTERN }),
      name: issues.string(r['name'], `${p}.name`),
      role: issues.oneOf(r['role'], PROFESSION_ROLES, `${p}.role`),
      finalAbility: issues.string(r['finalAbility'], `${p}.finalAbility`),
      playable: issues.boolean(r['playable'], `${p}.playable`),
    };
    if (def.id && professions.has(def.id)) issues.add(`${p}.id`, `identificador duplicado "${def.id}"`);
    if (issues.count === before) professions.set(def.id as string, def as ProfessionEntry);
  });

  const civilizations = new Map<string, CivilizationDefinition>();
  issues.array(issues.record(civRaw, '$civilizations')?.['civilizations'], '$civilizations.civilizations')?.forEach((entry, i) => {
    const p = `$civilizations.civilizations[${i}]`;
    const r = issues.record(entry, p);
    if (!r) return;
    const before = issues.count;
    const colors = issues.record(r['colors'], `${p}.colors`) ?? {};
    const list = (issues.array(r['professions'], `${p}.professions`) ?? []).filter(
      (x, j): x is string => issues.string(x, `${p}.professions[${j}]`, { pattern: ID_PATTERN }) !== undefined,
    );
    if (list.length !== PROFESSIONS_PER_CIVILIZATION) issues.add(`${p}.professions`, `cada civilización tiene ${PROFESSIONS_PER_CIVILIZATION} profesiones`);
    const def = {
      id: issues.string(r['id'], `${p}.id`, { pattern: ID_PATTERN }),
      name: issues.string(r['name'], `${p}.name`),
      tagline: issues.string(r['tagline'], `${p}.tagline`),
      region: issues.string(r['region'], `${p}.region`),
      colors: {
        primary: issues.string(colors['primary'], `${p}.colors.primary`, { pattern: HEX_COLOR_PATTERN }),
        secondary: issues.string(colors['secondary'], `${p}.colors.secondary`, { pattern: HEX_COLOR_PATTERN }),
      },
      professions: list,
    };
    for (const id of list) {
      const prof = professions.get(id);
      if (!prof) issues.add(`${p}.professions`, `profesión "${id}" inexistente`);
      else if (prof.civilizationId !== def.id) issues.add(`${p}.professions`, `la profesión "${id}" pertenece a "${prof.civilizationId}"`);
    }
    if (def.id && civilizations.has(def.id)) issues.add(`${p}.id`, `identificador duplicado "${def.id}"`);
    if (issues.count === before) civilizations.set(def.id as string, def as CivilizationDefinition);
  });
  for (const prof of professions.values()) {
    const civ = civilizations.get(prof.civilizationId);
    if (!civ) issues.add(`$professions[${prof.id}]`, `civilización "${prof.civilizationId}" inexistente`);
    else if (!civ.professions.includes(prof.id)) issues.add(`$professions[${prof.id}]`, `no figura en la lista de "${civ.id}"`);
  }
  issues.throwIfAny(source);
  return {
    civilizations,
    professions,
    civilization(id) {
      const c = civilizations.get(id);
      if (!c) throw new Error(`Civilización desconocida: "${id}"`);
      return c;
    },
    profession(id) {
      const p = professions.get(id);
      if (!p) throw new Error(`Profesión desconocida: "${id}"`);
      return p;
    },
    professionsOf(civilizationId) {
      return this.civilization(civilizationId).professions.map((id) => this.profession(id));
    },
  };
}
