import type Phaser from 'phaser';
import type { PlayerCharacter } from '../../core/character/playerCharacter.ts';
import type { Combatant } from '../../core/combat/combatant.ts';
import { TITLE_BAR_H } from './panel.ts';
import type { UiTheme } from './theme.ts';

const W = 220;
/** Retrato (96 × 96 a media escala) del tema Bosque. */
const PORTRAIT = 48;
/** Ancho total del marco completo (retrato + barras). */
export const FRAME_FULL_W = W + PORTRAIT + 12;
const TEXT = { fontFamily: 'monospace' } as const;

/**
 * Marco del personaje (GAME_DESIGN §12). Tema Bosque: retrato, nombre, nivel, vida, energía y XP.
 * Tema Clásico: ventana de «información básica» con barra de título (nombre), línea «Nv · etapa · XP %»
 * y barras de vida (verde) y energía (azul). En modo compacto (táctil) ambos temas usan 220 × 60.
 */
export class PlayerFrame {
  private readonly g: Phaser.GameObjects.Graphics;
  private readonly title: Phaser.GameObjects.Text;
  private readonly values: Phaser.GameObjects.Text;
  private readonly levelText: Phaser.GameObjects.Text;
  private readonly portrait: Phaser.GameObjects.Image | null;
  private readonly playerName: string;
  private readonly professionName: string;
  private readonly theme: UiTheme;
  private x = 0;
  private y = 0;
  private compact = false;
  /** Último estado dibujado: solo se redibuja si cambia. */
  private signature = '';

  constructor(scene: Phaser.Scene, x: number, y: number, playerName: string, professionName: string, theme: UiTheme, portraitKey: string | null = null) {
    this.playerName = playerName;
    this.professionName = professionName;
    this.theme = theme;
    this.g = scene.add.graphics();
    this.portrait = portraitKey ? scene.add.image(0, 0, portraitKey).setOrigin(0).setScale(PORTRAIT / 96) : null;
    this.title = scene.add.text(0, 0, '', { ...TEXT, fontSize: '13px', color: theme.text, stroke: theme.hudStroke, strokeThickness: theme.titleBar ? 0 : 3 });
    this.levelText = scene.add.text(0, 0, '', { ...TEXT, fontSize: '10px', color: '#1a1414' }).setOrigin(0.5, 0);
    this.values = scene.add.text(0, 0, '', { ...TEXT, fontSize: '11px', color: theme.textSoft, stroke: theme.hudStroke, strokeThickness: theme.titleBar ? 0 : 3 });
    this.layout(x, y, false);
  }

  /** Alto del marco en el modo actual. */
  get height(): number {
    return this.compact ? 60 : this.theme.titleBar ? TITLE_BAR_H + 62 : 88;
  }

  layout(x: number, y: number, compact: boolean): void {
    this.x = x;
    this.y = y;
    this.compact = compact;
    this.signature = '';
    const t = this.theme;
    this.portrait?.setPosition(x + 6, y + 6).setVisible(!compact && !t.titleBar);
    if (compact) {
      this.title.setPosition(x + 8, y + 4).setFontSize(11).setColor(t.text);
      this.levelText.setPosition(x + W - 10, y + 5).setOrigin(1, 0).setColor(t.heading).setStroke(t.hudStroke, t.titleBar ? 0 : 3).setFontSize(11);
      this.values.setPosition(x + 8, y + 44).setFontSize(10);
      return;
    }
    if (t.titleBar) {
      this.title.setPosition(x + 8, y + 7).setFontSize(12).setColor(t.titleText);
      this.levelText.setPosition(x + 8, y + TITLE_BAR_H + 5).setOrigin(0, 0).setColor(t.text).setStroke(t.hudStroke, 0).setFontSize(11);
      this.values.setPosition(x + 8, y + TITLE_BAR_H + 42).setFontSize(10);
      return;
    }
    this.title.setPosition(x + PORTRAIT + 12, y + 2).setFontSize(13).setColor(t.text);
    this.levelText.setPosition(x + 6 + PORTRAIT / 2, y + 56).setOrigin(0.5, 0).setColor('#1a1414').setStroke('#000', 0).setFontSize(10);
    this.values.setPosition(x + PORTRAIT + 12, y + 56).setFontSize(11);
  }

  update(c: Combatant, character: PlayerCharacter): void {
    const sig = `${Math.ceil(c.hp)}|${Math.floor(c.energy)}|${c.stats.life}|${c.stats.energy}|${c.level}|${character.xp}`;
    if (sig === this.signature) return;
    this.signature = sig;
    const { x, y } = this;
    const t = this.theme;
    const g = this.g.clear();
    const xp = character.levelProgress;
    const xpRatio = Number.isFinite(xp.needed) ? xp.current / xp.needed : 1;
    const xpText = `${xp.current}/${Number.isFinite(xp.needed) ? xp.needed : 'máx.'}`;
    const bar = (bx: number, by: number, bw: number, h: number, ratio: number, color: number) => {
      g.fillStyle(t.barBack, t.titleBar ? 1 : 0.8).fillRect(bx, by, bw, h);
      g.fillStyle(color, 1).fillRect(bx + 1, by + 1, Math.max(0, (bw - 2) * Math.min(1, ratio)), h - 2);
    };

    if (this.compact) {
      g.fillStyle(t.panelFill, t.titleBar ? 0.94 : 0.8).fillRoundedRect(x, y, W, 60, 6);
      g.lineStyle(2, t.panelStroke, 0.9).strokeRoundedRect(x, y, W, 60, 6);
      bar(x + 8, y + 20, W - 16, 8, c.hp / c.stats.life, t.hp);
      bar(x + 8, y + 30, W - 16, 7, c.energy / c.stats.energy, t.energy);
      bar(x + 8, y + 39, W - 16, 4, xpRatio, t.xp);
      this.title.setText(this.playerName);
      this.levelText.setText(`Nv ${c.level} · ${character.stage.name}`);
      this.values.setText(`Vida ${Math.ceil(c.hp)}/${Math.round(c.stats.life)} · Energía ${Math.floor(c.energy)} · XP ${xpText}`);
      return;
    }

    if (t.titleBar) {
      // Ventana de información básica: barra de título con el nombre, dos líneas y barras finas.
      const h = this.height;
      g.fillStyle(t.panelFill, t.panelAlpha).fillRect(x, y, FRAME_FULL_W, h);
      g.lineStyle(1, t.panelStroke, 1).strokeRect(x + 0.5, y + 0.5, FRAME_FULL_W - 1, h - 1);
      g.fillGradientStyle(t.titleFill, t.titleFill, t.titleFillDark, t.titleFillDark, 1).fillRect(x + 1, y + 1, FRAME_FULL_W - 2, TITLE_BAR_H);
      const pct = Number.isFinite(xp.needed) ? `${Math.floor(xpRatio * 100)} %` : 'máx.';
      bar(x + 20, y + TITLE_BAR_H + 22, FRAME_FULL_W - 28, 7, c.hp / c.stats.life, t.hp);
      bar(x + 20, y + TITLE_BAR_H + 31, FRAME_FULL_W - 28, 7, c.energy / c.stats.energy, t.energy);
      bar(x + 8, y + h - 9, FRAME_FULL_W - 16, 4, xpRatio, t.xp);
      this.title.setText(`${this.playerName} · ${this.professionName}`);
      this.levelText.setText(`Nv ${c.level} · ${character.stage.name} · XP ${pct}`);
      this.values.setText(`Vida ${Math.ceil(c.hp)}/${Math.round(c.stats.life)}   Energía ${Math.floor(c.energy)}/${Math.round(c.stats.energy)}`);
      // Marcas de color junto a cada barra.
      this.g.fillStyle(t.hp, 1).fillRect(x + 8, y + TITLE_BAR_H + 23, 8, 5);
      this.g.fillStyle(t.energy, 1).fillRect(x + 8, y + TITLE_BAR_H + 32, 8, 5);
      return;
    }

    g.fillStyle(t.panelFill, 0.8).fillRoundedRect(x, y, FRAME_FULL_W, 88, 6);
    g.lineStyle(2, t.panelStroke, 0.9).strokeRoundedRect(x, y, FRAME_FULL_W, 88, 6);
    // Retrato (hoja del Nivel A) o, si falta, un busto provisional.
    g.fillStyle(0x2b201c, 1).fillRect(x + 6, y + 6, PORTRAIT, PORTRAIT);
    if (!this.portrait) {
      g.fillStyle(0xd9a77a, 1).fillRect(x + 18, y + 16, 24, 24);
      g.fillStyle(0xb0503a, 1).fillRect(x + 14, y + 40, 32, 14);
    }
    g.fillStyle(0xe8c872, 1).fillRect(x + 6, y + 56, PORTRAIT, 12);
    const bx = x + PORTRAIT + 12;
    bar(bx, y + 22, W - 8, 8, c.hp / c.stats.life, t.hp);
    bar(bx, y + 33, W - 8, 8, c.energy / c.stats.energy, t.energy);
    bar(bx, y + 44, W - 8, 5, xpRatio, t.xp);
    this.title.setText(`${this.playerName} · ${this.professionName}`);
    this.levelText.setText(`Nv ${c.level}`);
    this.values.setText(
      `${character.stage.name} · Vida ${Math.ceil(c.hp)}/${Math.round(c.stats.life)} · Energía ${Math.floor(c.energy)}\nXP ${xpText}`,
    );
  }
}
