import type Phaser from 'phaser';

export interface EffectEntry {
  /** Clave del icono (16 × 16) o null para texto solo. */
  readonly icon: string | null;
  readonly text: string;
  readonly color: string;
}

const ICON = 16;
const GAP = 10;

/** Línea de infusión y estados activos del jugador: icono + texto con el tiempo restante, en fila. */
export class EffectsLine {
  private readonly scene: Phaser.Scene;
  private readonly style: Phaser.Types.GameObjects.Text.TextStyle;
  private items: Phaser.GameObjects.GameObject[] = [];
  private x = 0;
  private y = 0;
  private signature = '';

  constructor(scene: Phaser.Scene, style: Phaser.Types.GameObjects.Text.TextStyle) {
    this.scene = scene;
    this.style = style;
  }

  setPosition(x: number, y: number): void {
    this.x = x;
    this.y = y;
    this.signature = '';
  }

  update(entries: readonly EffectEntry[]): void {
    const sig = `${this.x},${this.y}|` + entries.map((e) => `${e.icon ?? ''}:${e.text}:${e.color}`).join('|');
    if (sig === this.signature) return;
    this.signature = sig;
    for (const o of this.items) o.destroy();
    this.items = [];
    let x = this.x;
    for (const e of entries) {
      if (e.icon) {
        this.items.push(this.scene.add.image(x, this.y + 1, e.icon).setOrigin(0, 0));
        x += ICON + 3;
      }
      const t = this.scene.add.text(x, this.y, e.text, { ...this.style, color: e.color });
      this.items.push(t);
      x += t.width + GAP;
    }
  }
}
