import Phaser from 'phaser';
import type { UseFailure } from '../../core/combat/combatWorld.ts';
import type { TouchInputState } from '../../core/input/touchInput.ts';
import type { TouchLayout } from '../../core/input/touchLayout.ts';
import { ACTION_SLOTS, type ActionSlot } from '../../core/professions/profession.ts';
import type { AbilityDefinition } from '../../core/combat/abilities.ts';
import type { SimEvent } from '../../core/simulation/worldSimulation.ts';
import { dayAt, formatHour } from '../../core/world/worldClock.ts';
import type { GameContent } from '../content.ts';
import { touchEnabledFor } from '../input/device.ts';
import { TouchControls } from '../input/touchControls.ts';
import { artOf, type ArtAssets } from '../rendering/artAssets.ts';
import { RARITY_COLORS } from '../rendering/itemIcons.ts';
import type { GameSession } from '../session.ts';
import { ActionBar } from '../ui/actionBar.ts';
import { BossBar } from '../ui/bossBar.ts';
import { EffectsLine, type EffectEntry } from '../ui/effectsLine.ts';
import { QuestTracker } from '../ui/questTracker.ts';
import { Minimap } from '../ui/minimap.ts';
import { LOG_W, NotificationFeed } from '../ui/notifications.ts';
import { activeTheme } from '../ui/panel.ts';
import { PlayerFrame } from '../ui/playerFrame.ts';
import { QuickSlotsView } from '../ui/quickSlots.ts';
import { ITEM_FAILURE_TEXT } from '../ui/texts.ts';
import type { UiTheme } from '../ui/theme.ts';
import { displayKey, REGISTRY_SETTINGS, type UserSettings } from '../input/settings.ts';
import type { GameScene } from './GameScene.ts';
import { REGISTRY_CONTENT, SceneKeys } from './keys.ts';

const MARGIN = 12;
/** Por debajo de este ancho o alto el minimapa se dibuja a la mitad. */
const SMALL_MINIMAP_WIDTH = 700;
const SMALL_MINIMAP_HEIGHT = 500;
/** Ancho mínimo para que el registro de mensajes (tema Clásico) no pise la barra de acciones. */
const LOG_MIN_WIDTH = 1016;
const FAILURE_TEXT: Readonly<Record<UseFailure, string>> = {
  energy: 'Energía insuficiente',
  cooldown: 'En recuperación',
  locked: 'Habilidad bloqueada',
  busy: '',
  dead: '',
};

/** HUD superpuesto, con cámara propia (no afectado por el seguimiento del mundo). */
export class HudScene extends Phaser.Scene {
  private session!: GameSession;
  private touch!: TouchInputState;
  private content!: GameContent;
  private art!: ArtAssets;
  private theme!: UiTheme;
  private minimap!: Minimap;
  private frame!: PlayerFrame;
  private actionBar!: ActionBar;
  private quickSlots!: QuickSlotsView;
  private touchControls: TouchControls | null = null;
  private feed!: NotificationFeed;
  private sectorLabel!: Phaser.GameObjects.Text;
  private hint!: Phaser.GameObjects.Text;
  private notice!: Phaser.GameObjects.Text;
  private prompt!: Phaser.GameObjects.Text;
  private effectsLine!: EffectsLine;
  private perfText!: Phaser.GameObjects.Text;
  private questTracker!: QuestTracker;
  private bossBar!: BossBar;
  private banner!: Phaser.GameObjects.Text;
  private deathOverlay!: Phaser.GameObjects.Rectangle;
  private noticeUntil = 0;
  private bannerUntil = 0;

  constructor() {
    super(SceneKeys.Hud);
  }

  init(data: { session: GameSession; touch: TouchInputState }): void {
    this.session = data.session;
    this.touch = data.touch;
    this.touchControls = null;
  }

  create(): void {
    this.content = this.registry.get(REGISTRY_CONTENT) as GameContent;
    this.art = artOf(this);
    const sim = this.session.sim;
    const theme = activeTheme(this);
    this.theme = theme;
    const TEXT = { fontFamily: 'monospace', color: theme.hudText, stroke: theme.hudStroke, strokeThickness: theme.hudStrokeThickness } as const;
    this.minimap = new Minimap(this, this.session, this.content.narrative, theme);
    this.frame = new PlayerFrame(this, MARGIN, MARGIN, this.content.character.name, this.content.profession.name, theme, this.art.portrait(sim.appearance));
    this.actionBar = new ActionBar(
      this,
      (['basic', 'power1', 'power2', 'power3', 'final', 'dodge'] as const).map((slot) => ({
        slot,
        key: '',
        ability: sim.abilityFor(slot),
      })),
      theme,
      (id) => this.art.skillIcon(id),
    );
    this.quickSlots = new QuickSlotsView(this, ['Q', 'F'], theme);
    this.feed = new NotificationFeed(this, theme);
    this.sectorLabel = this.add.text(0, 0, '', { ...TEXT, fontSize: '13px', align: 'right' }).setOrigin(1, 0);
    this.hint = this.add.text(0, 0, '', { ...TEXT, fontSize: '11px' }).setOrigin(0.5, 1).setAlpha(0.85);
    this.effectsLine = new EffectsLine(this, { ...TEXT, fontSize: '11px' });
    this.questTracker = new QuestTracker(this, theme);
    this.perfText = this.add.text(0, 0, '', { ...TEXT, fontSize: '11px', color: '#9fe870' }).setOrigin(0.5, 0);
    this.bossBar = new BossBar(this);
    this.prompt = this.add
      .text(0, 0, '', { ...TEXT, fontSize: '14px', color: '#f2efe0', backgroundColor: '#0b0d12cc', padding: { x: 8, y: 4 } })
      .setOrigin(0.5, 1)
      .setVisible(false);
    // En modo táctil el aviso de interacción es el botón para hablar o recolectar.
    this.prompt.setInteractive({ useHandCursor: true }).on(Phaser.Input.Events.GAMEOBJECT_POINTER_DOWN, () => {
      if (this.touchControls) this.touch.pressInteract();
    });
    this.deathOverlay = this.add.rectangle(0, 0, 10, 10, 0x2a0000, 0.45).setOrigin(0).setVisible(false);
    this.notice = this.add.text(0, 0, '', { ...TEXT, fontSize: '20px', color: '#ffd0c0' }).setOrigin(0.5);
    this.banner = this.add
      .text(0, 0, '', { ...TEXT, fontSize: '30px', color: '#ffd84a', strokeThickness: 6, align: 'center' })
      .setOrigin(0.5);

    this.applyKeyLabels();
    this.applyTouchMode();
    const onSettings = () => {
      // Un cambio de tema reconstruye el HUD entero con los colores nuevos.
      if (this.settings().uiTheme !== this.theme.id) {
        this.scene.restart({ session: this.session, touch: this.touch });
        return;
      }
      this.applyKeyLabels();
      this.applyTouchMode();
      this.layout(this.scale.width, this.scale.height);
    };
    this.registry.events.on(`changedata-${REGISTRY_SETTINGS}`, onSettings);

    const offEvents = this.session.onEvent((e) => { this.onSimEvent(e); });
    const offSave = this.session.onSave((kind, ok) => {
      if (kind === 'manual' || !ok) this.showNotice(ok ? 'Partida guardada' : 'No se pudo guardar', 1.5);
      else this.feed.push('Guardado automático', '#7a7f8c', this.session.sim.time);
    });
    this.layout(this.scale.width, this.scale.height);
    this.scale.on('resize', (size: Phaser.Structs.Size) => { this.layout(size.width, size.height); }, this);
    this.events.once(Phaser.Scenes.Events.SHUTDOWN, () => {
      offEvents();
      offSave();
      this.registry.events.off(`changedata-${REGISTRY_SETTINGS}`, onSettings);
      this.scale.off('resize', undefined, this);
      this.touchControls?.destroy();
      this.touchControls = null;
      this.minimap.destroy();
    });
  }

  private settings(): UserSettings {
    return this.registry.get(REGISTRY_SETTINGS) as UserSettings;
  }

  /** Crea o retira los controles táctiles según la configuración y el dispositivo. */
  private applyTouchMode(): void {
    const enabled = touchEnabledFor(this.settings());
    if (enabled && !this.touchControls) {
      const sim = this.session.sim;
      const abilities = Object.fromEntries(ACTION_SLOTS.map((s) => [s, sim.abilityFor(s)])) as Record<ActionSlot, AbilityDefinition>;
      this.touchControls = new TouchControls(this, this.touch, abilities, this.theme, (id) => this.art.skillIcon(id));
    } else if (!enabled && this.touchControls) {
      this.touchControls.destroy();
      this.touchControls = null;
    }
    this.actionBar.setVisible(!enabled);
    this.quickSlots.setVisible(!enabled);
    this.hint.setVisible(!enabled);
  }

  /** Estado de los controles táctiles para pruebas y depuración. */
  touchDebug(): { enabled: boolean; layout: TouchLayout | null } {
    return { enabled: this.touchControls !== null, layout: this.touchControls?.layoutInfo ?? null };
  }

  /** Etiquetas de teclas de la barra de acciones y de la ayuda, según la configuración actual. */
  private applyKeyLabels(): void {
    const b = this.settings().bindings;
    const k = (name: keyof typeof b) => displayKey(b[name][0]);
    this.actionBar.setKeyLabels({ basic: 'Clic', power1: k('power1'), power2: k('power2'), power3: k('power3'), final: k('final'), dodge: k('dodge') });
    this.quickSlots.setKeyLabels([k('quick1'), k('quick2')], k('inventory'));
    this.hint.setText(
      `${k('moveUp')}${k('moveLeft')}${k('moveDown')}${k('moveRight')} moverse · Clic atacar · ${k('power1')} ${k('power2')} ${k('power3')} poderes · ` +
        `${k('final')} final · ${k('dodge')} evadir · ${k('interact')} interactuar · ${k('inventory')} inventario · ` +
        `${k('alchemy')} alquimia · ${k('journal')} misiones · ${k('map')} mapa · Esc menú`,
    );
  }

  private itemName(itemId: string): string {
    return this.content.items.get(itemId).name;
  }

  private onSimEvent(e: SimEvent): void {
    const now = this.session.sim.time;
    switch (e.type) {
      case 'action-failed': {
        this.actionBar.flash(e.slot, now);
        const text = FAILURE_TEXT[e.reason];
        if (text) this.showNotice(text, 0.9);
        break;
      }
      case 'player-died':
        this.deathOverlay.setVisible(true);
        this.showNotice('Has caído. Reapareciendo…', 3);
        break;
      case 'player-respawned':
        this.deathOverlay.setVisible(false);
        this.noticeUntil = 0;
        break;
      case 'xp-gained':
        this.feed.push(`+${e.amount} XP`, '#9fe870', now);
        break;
      case 'level-up': {
        const unlocked = e.unlockedAbilities.map((id) => this.content.abilities.get(id).name);
        this.banner.setText(`¡Nivel ${e.level}!${unlocked.length > 0 ? `\nNueva habilidad: ${unlocked.join(', ')}` : ''}`);
        this.bannerUntil = now + 3;
        for (const name of unlocked) this.feed.push(`Nueva habilidad: ${name}`, '#ffd84a', now);
        break;
      }
      case 'drop-collected': {
        const rarity = this.content.items.get(e.itemId).rarity;
        const color = `#${RARITY_COLORS[rarity].toString(16).padStart(6, '0')}`;
        this.feed.push(`+${e.quantity} ${this.itemName(e.itemId)}`, color, now);
        break;
      }
      case 'inventory-full':
        this.showNotice('Inventario lleno', 1.5);
        break;
      case 'item-used':
        this.feed.push(`Usaste ${this.itemName(e.itemId)}`, '#c9c3b0', now);
        break;
      case 'alchemy-result': {
        const name = this.itemName(e.result.itemId);
        if (e.result.firstDiscovery) {
          this.banner.setText(`¡Receta descubierta!\n${name}`);
          this.bannerUntil = now + 3;
        }
        this.feed.push(`+${e.result.quantity} ${name}`, e.result.recipeId ? '#9fe870' : '#c9c3b0', now);
        break;
      }
      case 'infusion': {
        const el = this.content.elements.get(e.elementId);
        this.feed.push(`Ataques con ${el.name}`, el.color, now);
        break;
      }
      case 'quest-accepted':
        this.feed.push(`Nueva misión: ${this.content.quests.get(e.questId).name}`, '#e8c872', now);
        break;
      case 'quest-progress': {
        const q = this.content.quests.get(e.questId);
        const o = q.objectives.find((x) => x.id === e.objectiveId);
        if (o) this.feed.push(`${o.description}: ${e.current}/${e.count}`, '#e8c872', now);
        break;
      }
      case 'quest-completed':
        this.banner.setText(`Misión cumplida\n${this.content.quests.get(e.questId).name}`);
        this.bannerUntil = now + 2.5;
        break;
      case 'quest-turned-in':
        this.feed.push(`Misión entregada: ${this.content.quests.get(e.questId).name}`, '#9fe870', now);
        break;
      case 'boss-phase':
        this.banner.setText(`${this.session.sim.creatures.get(e.id)?.def.name ?? ''}\n${e.name}`);
        this.bannerUntil = now + 2;
        break;
      case 'boss-defeated':
        this.banner.setText(`¡${this.content.creatures.get(e.creatureId).name} derrotado!`);
        this.bannerUntil = now + 3.5;
        break;
      case 'harvested': {
        this.feed.push(`+${e.quantity} ${this.itemName(e.itemId)}`, '#9fe870', now);
        break;
      }
      case 'poi-reached':
        this.banner.setText(`Lugar descubierto\n${e.name}`);
        this.bannerUntil = now + 2.5;
        break;
      case 'interact-failed': {
        if (e.reason === 'regrowing') this.showNotice('Todavía no ha vuelto a crecer', 1.2);
        else if (e.reason === 'out-of-hours') this.showNotice('No se puede recolectar a esta hora', 1.2);
        break;
      }
      case 'item-failed': {
        const text = e.itemId === null && e.reason === 'missing' ? 'Ranura rápida vacía' : ITEM_FAILURE_TEXT[e.reason];
        if (text && !this.session.paused) this.showNotice(text, 1.2);
        break;
      }
      default:
        break;
    }
  }

  private showNotice(text: string, seconds: number): void {
    this.notice.setText(text);
    this.noticeUntil = this.session.sim.time + seconds;
  }

  /**
   * Distribución del HUD. En escritorio sigue GAME_DESIGN §12; en modo táctil el marco pasa a ser compacto y
   * se coloca junto a los controles (`computeTouchLayout`), el minimapa se reduce en pantallas estrechas y los
   * avisos se apartan de la columna de accesos.
   */
  private layout(width: number, height: number): void {
    this.minimap.setScale(width < SMALL_MINIMAP_WIDTH || height < SMALL_MINIMAP_HEIGHT ? 0.5 : 1);
    this.minimap.layout(width - MARGIN, MARGIN);
    const miniBottom = MARGIN + this.minimap.height + 12;
    this.sectorLabel.setPosition(width - MARGIN, miniBottom + 6);
    const reserveTop = miniBottom + 42;
    const l = this.touchControls?.layout(width, height, reserveTop) ?? null;
    // Registro tipo chat abajo a la izquierda (tema Clásico, escritorio ancho); si no, avisos flotantes que
    // no se dibujan sobre la columna de accesos ni sobre el racimo (apaisado).
    if (this.theme.feed === 'log' && !l && width >= LOG_MIN_WIDTH && width / 2 - this.actionBar.width / 2 > MARGIN + LOG_W) {
      this.feed.layout(MARGIN, height - MARGIN - 14, 'log');
    } else {
      let feedRight = width - MARGIN;
      if (l?.menuPlacement === 'column') feedRight = l.menu.inventory.x - 8;
      else if (l) feedRight = Math.min(feedRight, l.buttons.final.x - l.buttons.final.r - 8);
      this.feed.layout(feedRight, reserveTop + 4, 'floating');
    }
    this.actionBar.layout(width / 2, height - MARGIN - 16);
    this.quickSlots.layout(width - MARGIN, height - MARGIN);
    this.hint.setPosition(width / 2, height - 6);
    this.notice.setPosition(width / 2, height * 0.3);
    this.banner.setPosition(width / 2, height * 0.2);
    this.deathOverlay.setSize(width, height);

    if (l) {
      this.frame.layout(l.frame.x, l.frame.y, true);
      if (l.compact) {
        // Vertical: marco arriba a la izquierda (como en escritorio); efectos y misiones debajo de él; el aviso
        // de interacción, centrado sobre la banda de controles.
        const below = l.frame.y + l.frame.h;
        this.effectsLine.setPosition(l.frame.x, below + 6);
        // Bajo el marco y, en todo caso, bajo la etiqueta de sector (dos líneas) para no pisarla.
        this.questTracker.layout(MARGIN + 2, Math.max(below + 26, miniBottom + 48));
        this.bossBar.layout(width / 2, below + 18, width - 2 * MARGIN - 2 * (l.menu.inventory.w + 8));
        this.perfText.setPosition(width / 2, below + 52);
        this.prompt.setPadding(14, 10, 14, 10).setPosition(width / 2, l.controlsTop - 12);
        return;
      }
      const top = l.menuPlacement === 'row' ? l.menu.inventory.y + l.menu.inventory.h + 8 : MARGIN;
      this.effectsLine.setPosition(l.frame.x, l.frame.y - 16);
      this.questTracker.layout(MARGIN + 2, top + 4);
      this.bossBar.layout(width / 2, top + 18, width - 2 * MARGIN - (l.menuPlacement === 'column' ? 2 * (l.menu.inventory.w + 8) : 0));
      this.perfText.setPosition(width / 2, top + 52);
      this.prompt.setPadding(14, 10, 14, 10).setPosition(width / 2, l.frame.y - 26);
      return;
    }
    this.frame.layout(MARGIN, MARGIN, false);
    this.effectsLine.setPosition(MARGIN + 2, MARGIN + this.frame.height + 6);
    this.questTracker.layout(MARGIN + 2, MARGIN + this.frame.height + 26);
    this.bossBar.layout(width / 2, MARGIN + 18, width - 2 * MARGIN);
    this.perfText.setPosition(width / 2, MARGIN + 52);
    this.prompt.setPadding(8, 4, 8, 4).setPosition(width / 2, height - MARGIN - 90);
  }

  override update(): void {
    const sim = this.session.sim;
    const now = sim.time;
    this.minimap.update();
    this.frame.update(sim.player, sim.character);
    this.actionBar.update(sim.player, now);
    this.quickSlots.update(sim.character, now);
    this.touchControls?.update(sim.player, sim.character, now);
    this.feed.update(now);
    this.notice.setVisible(now < this.noticeUntil);
    this.banner.setVisible(now < this.bannerUntil);
    if (now < this.bannerUntil) this.banner.setAlpha(Math.min(1, this.bannerUntil - now));
    const { position } = this.session.player;
    const day = dayAt(this.content.clock, now);
    this.sectorLabel.setText(
      `${this.session.map.name}  (${Math.floor(position.x)}, ${Math.floor(position.y)})\nDía ${day} · ${formatHour(sim.hour)}`,
    );
    this.updatePrompt();
    this.updateEffects();
    this.questTracker.update(sim.quests, this.content.narrative, this.touchControls ? '' : displayKey(this.settings().bindings.interact[0]));
    this.updatePerf();
    const boss = [...sim.creatures.values()].find(
      (c) => c.boss !== null && (c.brain.state === 'chase' || c.combatant.hp < c.combatant.stats.life),
    );
    this.bossBar.update(boss ?? null);
  }

  /** Indicador de rendimiento (F3): FPS, tiempo de simulación y elementos dibujados. */
  private updatePerf(): void {
    const show = this.settings().showPerf;
    this.perfText.setVisible(show);
    if (!show) return;
    const game = this.scene.get(SceneKeys.Game) as GameScene;
    const { visible, total } = game.worldStats();
    this.perfText.setText(
      `FPS ${this.game.loop.actualFps.toFixed(0)} · simulación ${game.metrics.simMs.toFixed(2)} ms (pico ${game.metrics.worstSimMs.toFixed(1)}) · mapa ${visible}/${total}`,
    );
  }

  /** Infusión y estados activos del jugador, con su icono y tiempo restante. */
  private updateEffects(): void {
    const sim = this.session.sim;
    const entries: EffectEntry[] = [];
    const element = sim.player.activeElement(sim.time);
    if (element && sim.player.infusion) {
      const def = this.content.elements.get(element);
      const icon = this.art.elementIcon(element);
      entries.push({ icon, text: `${icon ? '' : '✦ '}${def.name} ${Math.ceil(sim.player.infusion.until - sim.time)} s`, color: def.color });
    }
    for (const s of sim.player.statuses.values()) {
      const icon = this.art.statusIcon(s.def.id);
      entries.push({ icon, text: `${icon ? '' : s.def.harmful ? '▼ ' : '▲ '}${s.def.name} ${Math.ceil(s.remaining)} s`, color: this.theme.hudText });
    }
    this.effectsLine.update(entries);
  }

  /** Aviso de interacción con el PNJ o la planta al alcance (GAME_DESIGN §12, tecla E o botón táctil). */
  private updatePrompt(): void {
    const target = this.session.paused ? null : this.session.sim.interactionTarget();
    if (!target) {
      this.prompt.setVisible(false);
      return;
    }
    const key = this.touchControls ? '' : `${displayKey(this.settings().bindings.interact[0])}: `;
    if (target.kind === 'npc') {
      this.prompt.setText(`${key}Hablar con ${target.name}`).setColor('#f2efe0').setVisible(true);
      return;
    }
    const plant = this.content.plants.get(target.node.plantId);
    const hours = plant.conditions.activeHours;
    let text = `${key}Recolectar ${plant.name}`;
    if (!target.ready) {
      const left = Math.ceil(target.node.readyAt - this.session.sim.time);
      text =
        left > 0
          ? `${plant.name}: vuelve a crecer en ${left} s`
          : `${plant.name}: solo de ${formatHour(hours?.[0] ?? 0)} a ${formatHour(hours?.[1] ?? 0)}`;
    }
    this.prompt.setText(text).setColor(target.ready ? '#f2efe0' : '#a9a596').setVisible(true);
  }
}
