import { screenDirToCellDir } from '../math/iso.ts';
import { length, type Vec2 } from '../math/vector.ts';
import type { ActionSlot } from '../professions/profession.ts';
import type { PlayerCommand } from '../simulation/worldSimulation.ts';

export type TouchMode = 'auto' | 'on' | 'off';
export const TOUCH_MODES: readonly TouchMode[] = ['auto', 'on', 'off'];
export type OverlayRequest = 'inventory' | 'alchemy' | 'journal' | 'map' | 'menu';

/** Decide si se muestran los controles táctiles: preferencia del usuario o, en automático, puntero grueso. */
export function resolveTouchMode(mode: TouchMode, coarsePointer: boolean): boolean {
  return mode === 'on' || (mode === 'auto' && coarsePointer);
}

/**
 * Estado de los controles táctiles, compartido entre el HUD (que lo escribe) y la escena de juego
 * (que lo lee cada fotograma). Las pulsaciones se encolan y se consumen una vez.
 */
export class TouchInputState {
  /** Dirección del joystick en pantalla (longitud 0 o 1). */
  move: Vec2 = { x: 0, y: 0 };
  private readonly actions: ActionSlot[] = [];
  private basicHeld = false;
  private basicHeldSince = false;
  private quick: number | null = null;
  private interact = false;
  private overlay: OverlayRequest | null = null;

  press(slot: ActionSlot): void {
    this.actions.push(slot);
  }

  /**
   * Ataque básico mantenido (el botón grande). Un toque que empieza y termina entre dos lecturas
   * cuenta igualmente como una pulsación.
   */
  holdBasic(held: boolean): void {
    if (held && !this.basicHeld) this.basicHeldSince = true;
    this.basicHeld = held;
  }

  pressQuick(index: number): void {
    this.quick = index;
  }

  pressInteract(): void {
    this.interact = true;
  }

  requestOverlay(key: OverlayRequest): void {
    this.overlay = key;
  }

  takeOverlay(): OverlayRequest | null {
    const o = this.overlay;
    this.overlay = null;
    return o;
  }

  /** Consume la siguiente acción en cola o, si no hay, el ataque básico mantenido. */
  takeAction(): { action: ActionSlot; pressed: boolean } | null {
    const queued = this.actions.shift();
    if (queued) return { action: queued, pressed: true };
    if (this.basicHeldSince) {
      this.basicHeldSince = false;
      return { action: 'basic', pressed: true };
    }
    return this.basicHeld ? { action: 'basic', pressed: false } : null;
  }

  /** Consume consumible rápido e interacción pulsados desde la última lectura. */
  takeExtras(): { quickSlot: number | null; interact: boolean } {
    const r = { quickSlot: this.quick, interact: this.interact };
    this.quick = null;
    this.interact = false;
    return r;
  }

  reset(): void {
    this.move = { x: 0, y: 0 };
    this.actions.length = 0;
    this.basicHeld = false;
    this.basicHeldSince = false;
    this.quick = null;
    this.interact = false;
    this.overlay = null;
  }
}

export interface KeyboardCommand {
  readonly move: Vec2;
  readonly action: ActionSlot | null;
  readonly quickSlot: number | null;
  readonly interact: boolean;
}

export interface PointerCommand {
  /** Apuntado hacia el puntero en celdas relativas al jugador. */
  readonly aimCells: Vec2 | null;
  /** Clic izquierdo nuevo desde el último fotograma. */
  readonly clickQueued: boolean;
  /** Botón izquierdo mantenido. */
  readonly held: boolean;
  /** El último puntero activo fue táctil. */
  readonly lastWasTouch: boolean;
}

/**
 * Combina teclado, ratón y controles táctiles en una orden por fotograma.
 * Prioridad de acción: tecla nueva > acción táctil en cola > clic o ratón mantenido > ataque táctil mantenido.
 * Con el modo táctil activo, un toque sobre el mundo no ataca (los botones ya lo hacen).
 */
export function composeCommand(input: {
  keyboard: KeyboardCommand;
  pointer: PointerCommand;
  touch: TouchInputState;
  touchEnabled: boolean;
}): PlayerCommand {
  const { keyboard, pointer, touch, touchEnabled } = input;
  const extras = touchEnabled ? touch.takeExtras() : null;
  const touchMove = touchEnabled && length(touch.move) > 0 ? touch.move : null;
  const move = length(keyboard.move) > 0 ? keyboard.move : (touchMove ?? { x: 0, y: 0 });

  let action: ActionSlot | null = keyboard.action;
  let pressed = action !== null;
  // Las acciones táctiles solo se consumen si no las adelanta una tecla (quedan en cola).
  const t = !action && touchEnabled ? touch.takeAction() : null;
  if (t && t.action !== 'basic') {
    action = t.action;
    pressed = true;
  }
  const pointerAttacks = !(touchEnabled && pointer.lastWasTouch);
  if (!action && pointerAttacks && (pointer.held || pointer.clickQueued)) {
    action = 'basic';
    pressed = pointer.clickQueued;
  }
  if (!action && t?.action === 'basic') {
    action = 'basic';
    pressed = t.pressed;
  }

  let aim: Vec2 | null = null;
  if (!(touchEnabled && pointer.lastWasTouch)) aim = pointer.aimCells;
  else if (touchMove) aim = screenDirToCellDir(touchMove);

  return {
    move,
    aim,
    action,
    pressed,
    quickSlot: keyboard.quickSlot ?? extras?.quickSlot ?? null,
    interact: keyboard.interact || (extras?.interact ?? false),
  };
}
