import type { SimulationContent } from '../simulation/worldSimulation.ts';
import type { TileCatalog } from '../world/tileCatalog.ts';
import type { ArtReferences } from './artMap.ts';
import type { PaletteCatalog } from './palette.ts';

/** Ranuras de equipo con capa dibujada sobre el cuerpo (ART_SPEC §3, Nivel A: arma y casco). */
export const LAYERED_EQUIP_SLOTS = ['weapon', 'head'] as const;

/** Identificadores del contenido cargado que deben tener arte asignado. */
export function artReferencesFrom(content: SimulationContent, catalog: TileCatalog, palettes: PaletteCatalog): ArtReferences {
  const items = [...content.items.all.values()];
  return {
    tileIds: catalog.tiles.keys(),
    creatureAtlases: [...content.creatures.all.values()].map((c) => c.spriteAtlas),
    npcAtlases: [...content.narrative.npcs.values()].map((n) => n.spriteAtlas),
    plantIds: content.plants.all.keys(),
    itemIds: content.items.all.keys(),
    layeredItemIds: items.filter((i) => i.equip && (LAYERED_EQUIP_SLOTS as readonly string[]).includes(i.equip.slot)).map((i) => i.id),
    playerAbilityIds: Object.values(content.profession.abilities),
    statusIds: content.statuses.all.keys(),
    elementIds: content.elements.all.keys(),
    vfxKeys: new Set([...content.abilities.all.values()].map((a) => a.vfx)),
    paletteIds: palettes.all.keys(),
  };
}
