import { Issues, type Json } from '../data/validate.ts';
import type { SheetCatalog } from './spriteSheets.ts';

/** Variantes del personaje jugable dibujadas (ART_SPEC §2). */
export const PLAYER_APPEARANCES = ['m', 'f'] as const;
export type PlayerAppearance = (typeof PLAYER_APPEARANCES)[number];
export const DEFAULT_APPEARANCE: PlayerAppearance = 'm';

export function isPlayerAppearance(v: unknown): v is PlayerAppearance {
  return typeof v === 'string' && (PLAYER_APPEARANCES as readonly string[]).includes(v);
}

/** Efectos que el motor reproduce por su cuenta (no vienen del campo `vfx` de una habilidad). */
export const ENGINE_VFX = ['impact', 'crit', 'level-up', 'drop-halo'] as const;

/**
 * Correspondencia entre identificadores del juego y hojas de arte (`data/art/content-map.json`).
 * Cada mapa va de ID del juego (o clave `ph-*` de atlas) a ID de hoja del catálogo.
 */
export interface ArtMap {
  readonly player: Readonly<Record<PlayerAppearance, string>>;
  readonly portraits: Readonly<Record<PlayerAppearance, string>>;
  /** Pieza de torso → paleta de sustitución del cuerpo base. */
  readonly bodyPalettes: Readonly<Record<string, string>>;
  /** Objeto equipable → hoja de capa (casco o arma). */
  readonly equipment: Readonly<Record<string, string>>;
  readonly tiles: Readonly<Record<string, string>>;
  /** Clave `spriteAtlas` de la criatura → hoja. */
  readonly creatures: Readonly<Record<string, string>>;
  /** Habilidad de criatura → nombre de animación en su hoja (si no está, se usa `attack`). */
  readonly creatureAnimations: Readonly<Record<string, string>>;
  readonly obstacle: string;
  readonly npcs: Readonly<Record<string, string>>;
  readonly plants: Readonly<Record<string, string>>;
  readonly items: Readonly<Record<string, string>>;
  /** Objetos que siguen con icono provisional (pendientes de la siguiente entrega de arte). */
  readonly itemsWithoutArt: readonly string[];
  readonly skills: Readonly<Record<string, string>>;
  readonly statuses: Readonly<Record<string, string>>;
  readonly elements: Readonly<Record<string, string>>;
  readonly vfx: Readonly<Record<string, string>>;
  readonly font: string;
}

function stringMap(issues: Issues, raw: unknown, path: string): Record<string, string> {
  const out: Record<string, string> = {};
  const r = issues.record(raw, path);
  if (!r) return out;
  for (const [k, v] of Object.entries(r)) {
    const s = issues.string(v, `${path}.${k}`);
    if (s) out[k] = s;
  }
  return out;
}

function appearanceMap(issues: Issues, raw: unknown, path: string): Record<PlayerAppearance, string> {
  const m = stringMap(issues, raw, path);
  for (const a of PLAYER_APPEARANCES) if (!(a in m)) issues.add(`${path}.${a}`, 'falta la variante');
  return { m: m['m'] ?? '', f: m['f'] ?? '' };
}

export function parseArtMap(raw: unknown, source = 'data/art/content-map.json'): ArtMap {
  const issues = new Issues();
  const r: Json = issues.record(raw, '$') ?? {};
  const itemsWithoutArt: string[] = [];
  issues.array(r['itemsWithoutArt'], '$.itemsWithoutArt')?.forEach((v, i) => {
    const s = issues.string(v, `$.itemsWithoutArt[${i}]`);
    if (s) itemsWithoutArt.push(s);
  });
  const map: ArtMap = {
    player: appearanceMap(issues, r['player'], '$.player'),
    portraits: appearanceMap(issues, r['portraits'], '$.portraits'),
    bodyPalettes: stringMap(issues, r['bodyPalettes'], '$.bodyPalettes'),
    equipment: stringMap(issues, r['equipment'], '$.equipment'),
    tiles: stringMap(issues, r['tiles'], '$.tiles'),
    creatures: stringMap(issues, r['creatures'], '$.creatures'),
    creatureAnimations: stringMap(issues, r['creatureAnimations'], '$.creatureAnimations'),
    obstacle: issues.string(r['obstacle'], '$.obstacle') ?? '',
    npcs: stringMap(issues, r['npcs'], '$.npcs'),
    plants: stringMap(issues, r['plants'], '$.plants'),
    items: stringMap(issues, r['items'], '$.items'),
    itemsWithoutArt,
    skills: stringMap(issues, r['skills'], '$.skills'),
    statuses: stringMap(issues, r['statuses'], '$.statuses'),
    elements: stringMap(issues, r['elements'], '$.elements'),
    vfx: stringMap(issues, r['vfx'], '$.vfx'),
    font: issues.string(r['font'], '$.font') ?? '',
  };
  issues.throwIfAny(source);
  return map;
}

/** Identificadores del juego contra los que se comprueba la correspondencia. */
export interface ArtReferences {
  readonly tileIds: Iterable<string>;
  readonly creatureAtlases: Iterable<string>;
  readonly npcAtlases: Iterable<string>;
  readonly plantIds: Iterable<string>;
  readonly itemIds: Iterable<string>;
  /** Objetos equipables en las ranuras con capa dibujada (arma y cabeza). */
  readonly layeredItemIds: Iterable<string>;
  readonly playerAbilityIds: Iterable<string>;
  readonly statusIds: Iterable<string>;
  readonly elementIds: Iterable<string>;
  readonly vfxKeys: Iterable<string>;
  readonly paletteIds: Iterable<string>;
}

/** Todas las hojas referenciadas por la correspondencia. */
export function referencedSheets(map: ArtMap): Set<string> {
  const ids = new Set<string>();
  for (const table of [map.player, map.portraits, map.equipment, map.tiles, map.creatures, map.npcs, map.plants, map.items, map.skills, map.statuses, map.elements, map.vfx]) {
    for (const v of Object.values(table)) ids.add(v);
  }
  ids.add(map.obstacle);
  ids.add(map.font);
  return ids;
}

/**
 * Comprueba que cada ID del juego tiene hoja (o está declarado sin arte) y que cada hoja referenciada
 * existe y es de la categoría esperada. Devuelve los problemas, sin lanzar.
 */
export function validateArtMap(map: ArtMap, sheets: SheetCatalog, refs: ArtReferences): string[] {
  const problems: string[] = [];
  const expectSheet = (id: string, path: string, categories: readonly string[]) => {
    if (!sheets.has(id)) {
      problems.push(`${path}: la hoja "${id}" no existe`);
      return;
    }
    const cat = sheets.get(id).category;
    if (!categories.includes(cat)) problems.push(`${path}: la hoja "${id}" es de categoría "${cat}", se esperaba ${categories.join('|')}`);
  };
  const cover = (table: Readonly<Record<string, string>>, ids: Iterable<string>, path: string, categories: readonly string[], optional: ReadonlySet<string> = new Set()) => {
    const known = new Set(ids);
    for (const id of known) {
      if (table[id] === undefined && !optional.has(id)) problems.push(`${path}: "${id}" no tiene hoja asignada`);
    }
    for (const [id, sheet] of Object.entries(table)) {
      if (!known.has(id)) problems.push(`${path}.${id}: no corresponde a ningún ID del juego`);
      expectSheet(sheet, `${path}.${id}`, categories);
    }
  };

  for (const a of PLAYER_APPEARANCES) {
    expectSheet(map.player[a], `$.player.${a}`, ['player']);
    expectSheet(map.portraits[a], `$.portraits.${a}`, ['portrait']);
  }
  const palettes = new Set(refs.paletteIds);
  const items = new Set(refs.itemIds);
  for (const [item, palette] of Object.entries(map.bodyPalettes)) {
    if (!items.has(item)) problems.push(`$.bodyPalettes.${item}: objeto desconocido`);
    if (!palettes.has(palette)) problems.push(`$.bodyPalettes.${item}: paleta "${palette}" desconocida`);
  }
  cover(map.equipment, refs.layeredItemIds, '$.equipment', ['equipment']);
  cover(map.tiles, refs.tileIds, '$.tiles', ['ground', 'world-object']);
  cover(map.creatures, refs.creatureAtlases, '$.creatures', ['enemy', 'fauna', 'boss']);
  expectSheet(map.obstacle, '$.obstacle', ['obstacle']);
  cover(map.npcs, refs.npcAtlases, '$.npcs', ['npc']);
  cover(map.plants, refs.plantIds, '$.plants', ['plant']);
  const withoutArt = new Set(map.itemsWithoutArt);
  for (const id of withoutArt) {
    if (!items.has(id)) problems.push(`$.itemsWithoutArt: "${id}" no es un objeto del juego`);
    if (map.items[id] !== undefined) problems.push(`$.itemsWithoutArt: "${id}" también tiene icono asignado`);
  }
  cover(map.items, items, '$.items', ['item'], withoutArt);
  const usedIcons = new Map<string, string>();
  for (const [id, sheet] of Object.entries(map.items)) {
    const other = usedIcons.get(sheet);
    if (other !== undefined) problems.push(`$.items.${id}: el icono "${sheet}" ya se usa para "${other}"`);
    usedIcons.set(sheet, id);
  }
  cover(map.skills, refs.playerAbilityIds, '$.skills', ['skill']);
  cover(map.statuses, refs.statusIds, '$.statuses', ['status']);
  cover(map.elements, refs.elementIds, '$.elements', ['element']);
  cover(map.vfx, [...refs.vfxKeys, ...ENGINE_VFX], '$.vfx', ['vfx']);
  expectSheet(map.font, '$.font', ['font']);
  for (const [abilityId, animation] of Object.entries(map.creatureAnimations)) {
    const drawn = Object.values(map.creatures).some((id) => sheets.has(id) && sheets.get(id).rows.some((r) => r.animation === animation));
    if (!drawn) problems.push(`$.creatureAnimations.${abilityId}: ninguna hoja de criatura tiene la animación "${animation}"`);
  }
  return problems;
}
