export const THEMES: Readonly<Record<UiThemeId, UiTheme>> = { bosque: BOSQUE, clasico: CLASICO };
export const DEFAULT_THEME: UiThemeId = 'clasico';

export function isThemeId(v: unknown): v is UiThemeId {
  return typeof v === 'string' && (UI_THEME_IDS as readonly string[]).includes(v);
}

/** Papel de cada color de la paleta histórica (tema Bosque), para traducirlo al tema activo. */
const LEGACY_ROLES: Readonly<Record<string, keyof Pick<UiTheme, 'heading' | 'text' | 'textSoft' | 'muted' | 'good' | 'warn' | 'danger'>>> = {
  '#e8c872': 'heading',
  '#e6e1cf': 'text',
  '#f2efe0': 'text',
  '#c9c3b0': 'textSoft',
  '#a9a596': 'muted',
  '#7a7f8c': 'muted',
  '#6a6f7c': 'muted',
  '#5a5f6c': 'muted',
  '#9fe870': 'good',
  '#ffd84a': 'warn',
  '#f2d16b': 'warn',
  '#ff6a5a': 'danger',
  '#ff9a7a': 'danger',
};

/** Convierte un color de la paleta del tema Bosque a su equivalente en `theme`; otros colores se respetan. */
export function themeColor(theme: UiTheme, color: string): string {
  const role = LEGACY_ROLES[color.toLowerCase()];
  return role ? theme[role] : color;
}

export const hex = (n: number): string => `#${n.toString(16).padStart(6, '0')}`;
