import Phaser from 'phaser';
import { animationKey, findRow, hasAnimation, resolveDirection, rowDuration } from '../../core/art/spriteSheets.ts';
import { cellToScreen, type IsoMetrics } from '../../core/math/iso.ts';
import type { CreatureInstance } from '../../core/simulation/worldSimulation.ts';
import { SHADOW_TEXTURE, type ArtAssets, type ArtLayer } from '../rendering/artAssets.ts';
import { ENTITY_DEPTH_BIAS, sortedDepth } from '../rendering/depth.ts';
import { CREATURE_ORIGIN_Y } from '../rendering/placeholderTextures.ts';
import { applyCombatVisuals, HealthBar } from './combatVisuals.ts';

const HURT_FLASH = 0.1;

/**
 * Representación de una criatura. Con arte del Nivel A reproduce reposo, marcha, ataque (o la animación
 * propia de la habilidad), alerta, daño y muerte; sin arte, el placeholder de dos fotogramas.
 * Se destruye con una animación al ser derrotada.
 */
export class CreatureView {
  private readonly sprite: Phaser.GameObjects.Sprite;
  private readonly shadow: Phaser.GameObjects.Image | null;
  private readonly layer: ArtLayer | null;
  private readonly bar: HealthBar;
  private readonly alertMark: Phaser.GameObjects.Text;
  private readonly iso: IsoMetrics;
  private readonly scene: Phaser.Scene;
  private readonly art: ArtAssets;
  private hurtFlashUntil = 0;
  private telegraphUntil = 0;
  private attackUntil = 0;
  private attackAnimation = 'attack';
  private transitionUntil = 0;
  private restart = false;
  private readonly isBoss: boolean;
  /** Altura visible del sprite, para colocar la barra de vida y el aviso sobre la cabeza. */
  private readonly top: number;

  constructor(scene: Phaser.Scene, creature: CreatureInstance, iso: IsoMetrics, art: ArtAssets) {
    this.scene = scene;
    this.iso = iso;
    this.art = art;
    this.isBoss = creature.def.category === 'boss';
    const key = creature.def.spriteAtlas;
    this.layer = art.creature(key);
    if (this.layer) {
      const { origin, frame } = this.layer.sheet;
      this.sprite = scene.add.sprite(0, 0, this.layer.key, 0).setOrigin(origin.x, origin.y);
      this.sprite.play(animationKey(this.layer.key, 'idle', this.layer.sheet.directions[0] ?? 'none'));
      const w = frame.width / 48;
      this.shadow = scene.add.image(0, 0, SHADOW_TEXTURE).setScale(w * 0.8, w * 0.6);
      this.top = frame.height * origin.y + 6;
    } else {
      this.sprite = scene.add.sprite(0, 0, key, 0).setOrigin(0.5, CREATURE_ORIGIN_Y);
      this.sprite.play(`${key}-idle`);
      // Los jefes provisionales se dibujan al doble de tamaño; su vida se muestra en el HUD.
      if (this.isBoss) this.sprite.setScale(2);
      this.shadow = null;
      this.top = 38;
    }
    this.sprite.setAlpha(0);
    scene.tweens.add({ targets: this.sprite, alpha: 1, duration: 400 });
    this.bar = new HealthBar(scene);
    this.alertMark = scene.add
      .text(0, 0, '!', { fontFamily: 'monospace', fontSize: '16px', color: '#ffd84a', stroke: '#000', strokeThickness: 4 })
      .setOrigin(0.5, 1)
      .setVisible(false);
  }

  hurt(time: number): void {
    this.hurtFlashUntil = time + HURT_FLASH;
  }

  telegraph(until: number): void {
    this.telegraphUntil = until;
  }

  clearTelegraph(): void {
    this.telegraphUntil = 0;
  }

  /** Inicia la animación de una habilidad hasta `until` (preparación más impactos). */
  act(abilityId: string, until: number): void {
    this.attackAnimation = this.art.creatureAnimation(abilityId) ?? 'attack';
    this.attackUntil = until;
    this.restart = true;
  }

  /** Cambio de fase del jefe: animación de transición si la hoja la tiene. */
  phaseTransition(time: number): void {
    if (!this.layer) return;
    const row = findRow(this.layer.sheet, 'phase-transition', this.layer.sheet.directions[0] ?? 'none');
    if (row) this.transitionUntil = time + rowDuration(row);
    this.restart = true;
  }

  private animationFor(c: CreatureInstance, time: number): string {
    const sheet = this.layer?.sheet;
    if (!sheet) return 'idle';
    if (time < this.hurtFlashUntil && hasAnimation(sheet, 'hurt')) return 'hurt';
    if (time < this.transitionUntil) return 'phase-transition';
    if (time < this.attackUntil) {
      if (hasAnimation(sheet, this.attackAnimation)) return this.attackAnimation;
      if (hasAnimation(sheet, 'attack')) return 'attack';
    }
    const alert = c.brain.state === 'alert' || c.brain.state === 'flee';
    if (alert && !c.motion.moving && hasAnimation(sheet, 'alert')) return 'alert';
    return c.motion.moving && hasAnimation(sheet, 'walk') ? 'walk' : 'idle';
  }

  sync(c: CreatureInstance, time: number): void {
    const p = cellToScreen(c.combatant.position, this.iso);
    const depth = sortedDepth(p.y) + ENTITY_DEPTH_BIAS;
    this.sprite.setPosition(p.x, p.y).setDepth(depth);
    if (this.layer) {
      const { direction, flipX } = resolveDirection(this.layer.sheet, c.motion.facing);
      const key = animationKey(this.layer.key, this.animationFor(c, time), direction);
      if (this.restart || this.sprite.anims.currentAnim?.key !== key) this.sprite.play(key, !this.restart);
      this.restart = false;
      this.sprite.setFlipX(flipX);
      this.shadow?.setPosition(p.x, p.y - 1).setDepth(depth - 0.05);
    } else {
      // Las texturas provisionales miran a la derecha: se espejan según la orientación.
      this.sprite.setFlipX(c.motion.facing.includes('w'));
    }
    applyCombatVisuals(this.sprite, c.combatant, time, this.hurtFlashUntil, this.telegraphUntil);
    if (!this.isBoss) this.bar.draw(p.x, p.y - this.top, c.combatant.hp / c.combatant.stats.life, depth + 0.2);
    // Estado de alerta de la fauna (GAME_DESIGN §8).
    const alert = c.brain.state === 'alert' || c.brain.state === 'flee';
    this.alertMark.setVisible(alert).setPosition(p.x, p.y - this.top - 2).setDepth(depth + 0.3);
    this.alertMark.setColor(c.brain.state === 'flee' ? '#ff8a3a' : '#ffd84a');
  }

  /** Desaparición silenciosa (fuera de horario, lejos del jugador). */
  despawn(): void {
    this.bar.destroy();
    this.alertMark.destroy();
    const targets: Phaser.GameObjects.GameObject[] = this.shadow ? [this.sprite, this.shadow] : [this.sprite];
    this.scene.tweens.add({ targets, alpha: 0, duration: 400, onComplete: () => { targets.forEach((t) => { t.destroy(); }); } });
  }

  /** Animación de derrota y liberación de recursos. */
  defeat(): void {
    this.bar.destroy();
    this.alertMark.destroy();
    const shadow = this.shadow;
    if (this.layer && hasAnimation(this.layer.sheet, 'death')) {
      const { direction, flipX } = resolveDirection(this.layer.sheet, this.sprite.flipX ? 'e' : 'w');
      this.sprite.clearTint().setFlipX(flipX);
      this.sprite.play(animationKey(this.layer.key, 'death', direction));
      shadow?.setVisible(false);
      this.sprite.once(Phaser.Animations.Events.ANIMATION_COMPLETE, () => {
        this.scene.tweens.add({ targets: this.sprite, alpha: 0, duration: 600, delay: 250, onComplete: () => { this.sprite.destroy(); } });
      });
      shadow?.destroy();
      return;
    }
    shadow?.destroy();
    this.sprite.setTintFill(0xffffff);
    this.scene.tweens.add({
      targets: this.sprite,
      alpha: 0,
      scaleX: this.sprite.scaleX * 1.4,
      scaleY: this.sprite.scaleY * 0.2,
      duration: 350,
      onComplete: () => { this.sprite.destroy(); },
    });
  }
}
