import type Phaser from 'phaser';
import { resolveFrame } from '../../core/art/spriteSheets.ts';
import type { PlantNode } from '../../core/ecosystem/plants.ts';
import { cellToScreen, type IsoMetrics } from '../../core/math/iso.ts';
import type { ArtAssets } from '../rendering/artAssets.ts';
import { sortedDepth } from '../rendering/depth.ts';
import { plantTextureKey } from '../rendering/placeholderTextures.ts';

/**
 * Planta recolectable. Con arte: fotograma «madura» o «regenerándose» (ART_SPEC §7). Sin arte: color
 * pleno cuando está lista; atenuada en crecimiento o fuera de horario.
 */
export class PlantView {
  private readonly sprite: Phaser.GameObjects.Image;
  private readonly frames: { readonly mature: number; readonly regrowing: number } | null;
  private ready: boolean | null = null;

  constructor(scene: Phaser.Scene, node: PlantNode, iso: IsoMetrics, art: ArtAssets) {
    const p = cellToScreen(node.position, iso);
    const layer = art.plant(node.plantId);
    if (layer) {
      const mature = resolveFrame(layer.sheet, 'mature', null, 0)?.index ?? 0;
      const regrowing = resolveFrame(layer.sheet, 'regrowing', null, 0)?.index ?? mature;
      this.frames = { mature, regrowing };
      this.sprite = scene.add.image(p.x, p.y, layer.key, mature).setOrigin(layer.sheet.origin.x, layer.sheet.origin.y);
    } else {
      this.frames = null;
      this.sprite = scene.add.image(p.x, p.y, plantTextureKey(node.plantId)).setOrigin(0.5, 25 / 28);
    }
    this.sprite.setDepth(sortedDepth(p.y));
  }

  sync(ready: boolean): void {
    if (ready === this.ready) return;
    this.ready = ready;
    if (this.frames) {
      this.sprite.setFrame(ready ? this.frames.mature : this.frames.regrowing).setAlpha(ready ? 1 : 0.85);
      return;
    }
    this.sprite.setAlpha(ready ? 1 : 0.35).setScale(ready ? 1 : 0.7);
    if (ready) this.sprite.clearTint();
    else this.sprite.setTint(0x8a8f7c);
  }
}
