import Phaser from 'phaser';
import type { PlayerCharacter } from '../../core/character/playerCharacter.ts';
import type { AbilityDefinition } from '../../core/combat/abilities.ts';
import type { Combatant } from '../../core/combat/combatant.ts';
import type { TouchInputState } from '../../core/input/touchInput.ts';
import {
  computeTouchLayout,
  TOUCH_ACTION_BUTTONS,
  TOUCH_MENU_BUTTONS,
  type Circle,
  type TouchActionButton,
  type TouchLayout,
  type TouchMenuButton,
} from '../../core/input/touchLayout.ts';
import { joystickState } from '../../core/input/virtualJoystick.ts';
import type { ActionSlot } from '../../core/professions/profession.ts';
import { itemIconKey } from '../rendering/itemIcons.ts';
import type { UiTheme } from '../ui/theme.ts';

const DEAD_ZONE = 0.18;
const DEPTH = 20;
const MENU_LABELS: Readonly<Record<TouchMenuButton, string>> = { inventory: 'INV', alchemy: 'ALQ', journal: 'MIS', map: 'MAPA', menu: 'MENÚ' };
const ACTION_SLOT_BUTTONS = ['basic', 'power1', 'power2', 'power3', 'final', 'dodge'] as const satisfies readonly ActionSlot[];

/**
 * Controles táctiles en el HUD: joystick virtual, racimo de acciones, consumibles rápidos y columna de
 * accesos. Escribe en `TouchInputState`; la distribución es `computeTouchLayout` (core, probada).
 */
export class TouchControls {
  private readonly scene: Phaser.Scene;
  private readonly state: TouchInputState;
  private readonly abilities: Readonly<Record<ActionSlot, AbilityDefinition>>;
  private readonly theme: UiTheme;
  private readonly statics: Phaser.GameObjects.Graphics;
  private readonly dynamics: Phaser.GameObjects.Graphics;
  private readonly zones = new Map<string, Phaser.GameObjects.Zone>();
  private readonly labels = new Map<string, Phaser.GameObjects.Text>();
  private readonly timers = new Map<TouchActionButton, Phaser.GameObjects.Text>();
  private readonly icons = new Map<ActionSlot, Phaser.GameObjects.Image>();
  private readonly quickIcons: Phaser.GameObjects.Image[] = [];
  private readonly pressedUntil = new Map<string, number>();
  private stickPointer: Phaser.Input.Pointer | null = null;
  private basicPointer: Phaser.Input.Pointer | null = null;
  private knob = { x: 0, y: 0 };
  private current: TouchLayout;
  private signature = '';

  private readonly onMove = (p: Phaser.Input.Pointer) => {
    if (p === this.stickPointer) this.updateStick(p);
  };
  private readonly onUp = (p: Phaser.Input.Pointer) => {
    if (p === this.stickPointer) this.releaseStick();
    if (p === this.basicPointer) this.releaseBasic();
  };

  constructor(
    scene: Phaser.Scene,
    state: TouchInputState,
    abilities: Readonly<Record<ActionSlot, AbilityDefinition>>,
    theme: UiTheme,
    iconFor: (abilityId: string) => string | null = () => null,
  ) {
    this.scene = scene;
    this.state = state;
    this.abilities = abilities;
    this.theme = theme;
    this.statics = scene.add.graphics().setDepth(DEPTH);
    this.dynamics = scene.add.graphics().setDepth(DEPTH + 1);
    this.current = computeTouchLayout(scene.scale.width, scene.scale.height);
    const TEXT = { fontFamily: 'monospace', color: theme.slotLabel, stroke: '#000', strokeThickness: theme.titleBar ? 0 : 3 } as const;

    for (const id of ACTION_SLOT_BUTTONS) {
      const icon = iconFor(this.abilities[id].id);
      if (icon) this.icons.set(id, scene.add.image(0, 0, icon).setDepth(DEPTH + 2));
      const short = this.abilities[id].name.split(' ').map((w) => w[0]).join('').slice(0, 3);
      this.labels.set(id, scene.add.text(0, 0, short, { ...TEXT, fontSize: id === 'basic' ? '18px' : '13px' }).setOrigin(0.5).setDepth(DEPTH + 2).setVisible(icon === null));
      this.timers.set(id, scene.add.text(0, 0, '', { ...TEXT, fontSize: '12px', color: theme.slotKey, strokeThickness: icon ? 3 : TEXT.strokeThickness }).setOrigin(0.5).setDepth(DEPTH + 2));
      this.zone(id, () => {
        if (id === 'basic') return;
        this.state.press(id);
        this.flash(id);
      });
    }
    for (const id of ['quick1', 'quick2'] as const) {
      this.quickIcons.push(scene.add.image(0, 0, '__MISSING').setVisible(false).setDepth(DEPTH + 2));
      this.timers.set(id, scene.add.text(0, 0, '', { ...TEXT, fontSize: '10px' }).setOrigin(1, 1).setDepth(DEPTH + 2));
      this.zone(id, () => {
        this.state.pressQuick(id === 'quick1' ? 0 : 1);
        this.flash(id);
      });
    }
    for (const id of TOUCH_MENU_BUTTONS) {
      this.labels.set(id, scene.add.text(0, 0, MENU_LABELS[id], { ...TEXT, fontSize: '9px', color: theme.titleBar ? theme.titleText : theme.slotKey }).setOrigin(0.5).setDepth(DEPTH + 2));
      this.zone(id, () => {
        this.state.requestOverlay(id);
        this.flash(id);
      });
    }
    this.zone('joystick', (p) => {
      this.stickPointer = p;
      this.updateStick(p);
    });
    const basic = this.zones.get('basic');
    basic?.on(Phaser.Input.Events.GAMEOBJECT_POINTER_DOWN, (p: Phaser.Input.Pointer) => {
      this.basicPointer = p;
      this.state.holdBasic(true);
      this.flash('basic');
    });
    basic?.on(Phaser.Input.Events.GAMEOBJECT_POINTER_OUT, (p: Phaser.Input.Pointer) => {
      if (p === this.basicPointer) this.releaseBasic();
    });
    scene.input.on(Phaser.Input.Events.POINTER_MOVE, this.onMove);
    scene.input.on(Phaser.Input.Events.POINTER_UP, this.onUp);
    this.layout(scene.scale.width, scene.scale.height, 0);
  }

  get layoutInfo(): TouchLayout {
    return this.current;
  }

  private zone(id: string, onDown: (p: Phaser.Input.Pointer) => void): void {
    const z = this.scene.add.zone(0, 0, 10, 10).setDepth(DEPTH + 3);
    z.on(Phaser.Input.Events.GAMEOBJECT_POINTER_DOWN, onDown);
    this.zones.set(id, z);
  }

  private flash(id: string): void {
    this.pressedUntil.set(id, this.scene.time.now + 150);
  }

  private updateStick(p: Phaser.Input.Pointer): void {
    const j = this.current.joystick;
    const s = joystickState(j, { x: p.x, y: p.y }, j.r, DEAD_ZONE);
    this.state.move = s.vector;
    this.knob = s.knob;
  }

  private releaseStick(): void {
    this.stickPointer = null;
    this.state.move = { x: 0, y: 0 };
    this.knob = this.current.joystick;
  }

  private releaseBasic(): void {
    this.basicPointer = null;
    this.state.holdBasic(false);
  }

  /** Recoloca todo. `reserveTop` es la altura ocupada arriba a la derecha (minimapa y sector). */
  layout(width: number, height: number, reserveTop: number): TouchLayout {
    const l = computeTouchLayout(width, height, { reserveTop });
    this.current = l;
    this.knob = l.joystick;
    // setInteractive no actualiza un área ya registrada: se modifica la forma existente.
    const circle = (id: string, c: Circle, grip = 1) => {
      const z = this.zones.get(id);
      if (!z) return;
      const r = c.r * grip;
      z.setPosition(c.x, c.y).setSize(r * 2, r * 2, false);
      if (z.input) (z.input.hitArea as Phaser.Geom.Circle).setTo(r, r, r);
      else z.setInteractive(new Phaser.Geom.Circle(r, r, r), (s: Phaser.Geom.Circle, x: number, y: number) => Phaser.Geom.Circle.Contains(s, x, y));
    };
    circle('joystick', l.joystick, l.grip);
    for (const id of TOUCH_ACTION_BUTTONS) {
      const c = l.buttons[id];
      circle(id, c);
      this.labels.get(id)?.setPosition(c.x, c.y - (id === 'basic' ? 6 : 5));
      if (id !== 'quick1' && id !== 'quick2') this.icons.get(id)?.setPosition(c.x, c.y - (id === 'basic' ? 4 : 3)).setScale(id === 'basic' ? 1.5 : 1);
      const t = this.timers.get(id);
      if (id === 'quick1' || id === 'quick2') t?.setPosition(c.x + c.r - 4, c.y + c.r - 2);
      else t?.setPosition(c.x, c.y + (id === 'basic' ? 12 : 9));
    }
    this.quickIcons[0]?.setPosition(l.buttons.quick1.x, l.buttons.quick1.y);
    this.quickIcons[1]?.setPosition(l.buttons.quick2.x, l.buttons.quick2.y);
    for (const id of TOUCH_MENU_BUTTONS) {
      const m = l.menu[id];
      const z = this.zones.get(id);
      if (!z) continue;
      z.setPosition(m.x + m.w / 2, m.y + m.h / 2).setSize(m.w, m.h, false);
      if (z.input) (z.input.hitArea as Phaser.Geom.Rectangle).setTo(0, 0, m.w, m.h);
      else z.setInteractive(new Phaser.Geom.Rectangle(0, 0, m.w, m.h), (s: Phaser.Geom.Rectangle, x: number, y: number) => Phaser.Geom.Rectangle.Contains(s, x, y));
      this.labels.get(id)?.setPosition(m.x + m.w / 2, m.y + m.h / 2);
    }
    this.drawStatics();
    this.signature = '';
    return l;
  }

  private drawStatics(): void {
    const g = this.statics.clear();
    const l = this.current;
    const t = this.theme;
    g.fillStyle(t.touchFill, 0.45).fillCircle(l.joystick.x, l.joystick.y, l.joystick.r);
    g.lineStyle(2, t.touchStroke, 0.8).strokeCircle(l.joystick.x, l.joystick.y, l.joystick.r);
    for (const id of TOUCH_MENU_BUTTONS) {
      const m = l.menu[id];
      if (t.titleBar) g.fillGradientStyle(t.titleFill, t.titleFill, t.titleFillDark, t.titleFillDark, 0.92).fillRoundedRect(m.x, m.y, m.w, m.h, 6);
      else g.fillStyle(t.panelFill, 0.8).fillRoundedRect(m.x, m.y, m.w, m.h, 6);
      g.lineStyle(2, t.panelStroke, 0.9).strokeRoundedRect(m.x, m.y, m.w, m.h, 6);
    }
  }

  update(player: Combatant, character: PlayerCharacter, now: number): void {
    const l = this.current;
    const t = this.scene.time.now;
    const itemCd = character.itemCooldownRatio(now);
    const sig =
      ACTION_SLOT_BUTTONS.map((id) => {
        const a = this.abilities[id];
        return `${Math.ceil(player.cooldownRemaining(a.id, now) * 10)}${player.energy < a.energyCost ? 'e' : ''}${(this.pressedUntil.get(id) ?? 0) > t ? 'p' : ''}`;
      }).join(',') +
      `|${player.level}|${Math.round(this.knob.x)},${Math.round(this.knob.y)}|${Math.ceil(itemCd * 20)}|` +
      character.quickSlots.map((id) => (id ? `${id}:${character.inventory.count(id)}` : '-')).join(',') +
      [...TOUCH_MENU_BUTTONS, 'quick1', 'quick2'].map((id) => ((this.pressedUntil.get(id) ?? 0) > t ? 'p' : '')).join('');
    if (sig === this.signature) return;
    this.signature = sig;

    const g = this.dynamics.clear();
    const th = this.theme;
    const dark = th.titleBar ? 0.3 : 0.6;
    // Palanca del joystick.
    g.fillStyle(th.touchKnob, this.stickPointer ? 0.9 : 0.55).fillCircle(this.knob.x, this.knob.y, l.joystick.r * 0.45);

    for (const id of ACTION_SLOT_BUTTONS) {
      const c = l.buttons[id];
      const a = this.abilities[id];
      const remaining = player.cooldownRemaining(a.id, now);
      const total = a.category === 'basic' ? a.cooldown / player.stats.attackRate : a.cooldown;
      const noEnergy = player.energy < a.energyCost;
      const locked = player.level < a.unlockLevel;
      const pressed = (this.pressedUntil.get(id) ?? 0) > t;
      const basicFill = th.titleBar ? 0xffe4d2 : 0x2a1d1a;
      g.fillStyle(id === 'final' ? th.slotFinalFill : id === 'basic' ? basicFill : th.slotFill, 0.9).fillCircle(c.x, c.y, c.r);
      if (remaining > 0 && total > 0) {
        g.fillStyle(0x000000, dark);
        g.slice(c.x, c.y, c.r, -Math.PI / 2, -Math.PI / 2 + Math.PI * 2 * Math.min(1, remaining / total), false);
        g.fillPath();
      }
      if (noEnergy && !locked) g.fillStyle(0x1a3a6a, th.titleBar ? 0.25 : 0.45).fillCircle(c.x, c.y, c.r);
      if (locked) g.fillStyle(0x000000, th.titleBar ? 0.3 : 0.7).fillCircle(c.x, c.y, c.r);
      g.lineStyle(pressed ? 4 : 2, pressed ? 0xffffff : id === 'final' ? th.slotFinalStroke : id === 'basic' ? 0xd9a77a : th.slotStroke, 1).strokeCircle(c.x, c.y, c.r);
      const timer = remaining > 0.05 && total >= 1 ? remaining.toFixed(remaining < 3 ? 1 : 0) : '';
      this.timers.get(id)?.setText(locked ? `Nv ${a.unlockLevel}` : timer).setColor(locked ? th.slotKey : th.slotLabel);
      const alpha = locked ? 0.25 : remaining > 0 || noEnergy ? 0.5 : 1;
      this.labels.get(id)?.setAlpha(alpha);
      this.icons.get(id)?.setAlpha(alpha);
    }

    (['quick1', 'quick2'] as const).forEach((id, i) => {
      const c = l.buttons[id];
      const itemId = character.quickSlots[i] ?? null;
      const count = itemId ? character.inventory.count(itemId) : 0;
      const pressed = (this.pressedUntil.get(id) ?? 0) > t;
      g.fillStyle(th.slotFill, 0.9).fillCircle(c.x, c.y, c.r);
      if (itemId && itemCd > 0) {
        g.fillStyle(0x000000, dark);
        g.slice(c.x, c.y, c.r, -Math.PI / 2, -Math.PI / 2 + Math.PI * 2 * itemCd, false);
        g.fillPath();
      }
      g.lineStyle(pressed ? 4 : 2, pressed ? 0xffffff : th.slotStroke, 1).strokeCircle(c.x, c.y, c.r);
      const icon = this.quickIcons[i];
      if (itemId && icon) icon.setTexture(itemIconKey(itemId)).setVisible(true).setAlpha(count > 0 ? 1 : 0.3);
      else icon?.setVisible(false);
      this.timers.get(id)?.setText(itemId ? String(count) : '');
    });

    for (const id of TOUCH_MENU_BUTTONS) {
      if ((this.pressedUntil.get(id) ?? 0) > t) {
        const m = l.menu[id];
        g.lineStyle(3, 0xffffff, 1).strokeRoundedRect(m.x, m.y, m.w, m.h, 6);
      }
    }
  }

  destroy(): void {
    this.scene.input.off(Phaser.Input.Events.POINTER_MOVE, this.onMove);
    this.scene.input.off(Phaser.Input.Events.POINTER_UP, this.onUp);
    this.state.reset();
    this.statics.destroy();
    this.dynamics.destroy();
    for (const z of this.zones.values()) z.destroy();
    for (const t of this.labels.values()) t.destroy();
    for (const t of this.timers.values()) t.destroy();
    for (const i of this.icons.values()) i.destroy();
    for (const i of this.quickIcons) i.destroy();
  }
}
