import { ID_PATTERN, Issues } from '../data/validate.ts';

/**
 * Descriptores de hojas de sprites (docs/ART_SPEC.md §1 y §14): hojas rectangulares sin márgenes,
 * una fila por animación, filas agrupadas por dirección. Solo lógica pura; la carga en Phaser está en
 * `game/rendering/artAssets.ts`.
 */
export interface SheetRow {
  /** Fila absoluta dentro de la hoja. */
  readonly row: number;
  readonly frames: number;
  readonly animation: string;
  readonly direction: string;
  readonly fps: number;
  readonly loop: boolean;
}

export interface SheetDescriptor {
  readonly id: string;
  /** Ruta relativa a `public/art/`. */
  readonly image: string;
  readonly category: string;
  readonly width: number;
  readonly height: number;
  readonly frame: { readonly width: number; readonly height: number };
  readonly columns: number;
  /** Direcciones dibujadas, en el orden de los bloques de filas (vacío en recursos estáticos). */
  readonly directions: readonly string[];
  readonly rowsPerDirection: number;
  readonly rows: readonly SheetRow[];
  /** Direcciones obtenidas por reflejo horizontal: e → w, se → sw, ne → nw. */
  readonly mirror: Readonly<Record<string, string>>;
  readonly origin: { readonly x: number; readonly y: number };
  readonly glyphs: readonly string[] | null;
  readonly layer: string | null;
  readonly variant: string | null;
}

export interface SheetCatalog {
  readonly all: ReadonlyMap<string, SheetDescriptor>;
  get(id: string): SheetDescriptor;
  has(id: string): boolean;
}

function parseSheet(issues: Issues, id: string, raw: unknown, p: string): SheetDescriptor | undefined {
  const s = issues.record(raw, p);
  if (!s) return undefined;
  const image = issues.string(s['image'], `${p}.image`);
  const category = issues.string(s['category'], `${p}.category`);
  const width = issues.number(s['width'], `${p}.width`, { integer: true, min: 1 });
  const height = issues.number(s['height'], `${p}.height`, { integer: true, min: 1 });
  const frameRaw = issues.record(s['frame'], `${p}.frame`);
  const fw = frameRaw ? issues.number(frameRaw['width'], `${p}.frame.width`, { integer: true, min: 1 }) : undefined;
  const fh = frameRaw ? issues.number(frameRaw['height'], `${p}.frame.height`, { integer: true, min: 1 }) : undefined;
  const columns = issues.number(s['columns'], `${p}.columns`, { integer: true, min: 1 });
  const directions: string[] = [];
  issues.array(s['directions'], `${p}.directions`)?.forEach((d, i) => {
    const v = issues.string(d, `${p}.directions[${i}]`);
    if (v) directions.push(v);
  });
  const rowsPerDirection = issues.number(s['rowsPerDirection'], `${p}.rowsPerDirection`, { integer: true, min: 1 });
  const rows: SheetRow[] = [];
  issues.array(s['rows'], `${p}.rows`)?.forEach((r, i) => {
    const q = `${p}.rows[${i}]`;
    const o = issues.record(r, q);
    if (!o) return;
    const row = issues.number(o['row'], `${q}.row`, { integer: true, min: 0 });
    const frames = issues.number(o['frames'], `${q}.frames`, { integer: true, min: 1 });
    const animation = issues.string(o['animation'], `${q}.animation`);
    const direction = issues.string(o['direction'], `${q}.direction`);
    const fps = issues.number(o['fps'], `${q}.fps`, { min: 0 });
    const loop = issues.boolean(o['loop'], `${q}.loop`);
    if (row === undefined || frames === undefined || !animation || !direction || fps === undefined || loop === undefined) return;
    rows.push({ row, frames, animation, direction, fps, loop });
  });
  const mirror: Record<string, string> = {};
  const m = issues.record(s['mirror'], `${p}.mirror`);
  if (m) for (const [k, v] of Object.entries(m)) if (typeof v === 'string') mirror[k] = v;
  const originRaw = issues.record(s['origin'], `${p}.origin`);
  const ox = originRaw ? issues.number(originRaw['x'], `${p}.origin.x`, { min: 0, max: 1 }) : undefined;
  const oy = originRaw ? issues.number(originRaw['y'], `${p}.origin.y`, { min: 0, max: 1 }) : undefined;
  let glyphs: string[] | null = null;
  if (s['glyphs'] !== undefined) {
    glyphs = [];
    issues.array(s['glyphs'], `${p}.glyphs`)?.forEach((g, i) => {
      const v = issues.string(g, `${p}.glyphs[${i}]`);
      if (v) glyphs?.push(v);
    });
  }
  const layer = typeof s['layer'] === 'string' ? s['layer'] : null;
  const variant = typeof s['variant'] === 'string' ? s['variant'] : null;
  if (
    !image || !category || width === undefined || height === undefined || fw === undefined || fh === undefined ||
    columns === undefined || rowsPerDirection === undefined || ox === undefined || oy === undefined
  ) return undefined;

  // Coherencia geométrica: la cuadrícula debe cubrir exactamente la imagen.
  if (columns * fw !== width) issues.add(`${p}.columns`, `${columns} columnas × ${fw} px ≠ ancho ${width}`);
  if (height % fh !== 0) issues.add(`${p}.frame.height`, `la altura ${height} no es múltiplo de ${fh}`);
  const totalRows = height / fh;
  if (rows.length === 0) issues.add(`${p}.rows`, 'se esperaba al menos una fila');
  for (const [i, r] of rows.entries()) {
    if (r.row >= totalRows) issues.add(`${p}.rows[${i}].row`, `fila ${r.row} fuera de la hoja (${totalRows} filas)`);
    if (r.frames > columns) issues.add(`${p}.rows[${i}].frames`, `${r.frames} fotogramas en una hoja de ${columns} columnas`);
    if (r.direction !== 'none' && !directions.includes(r.direction)) issues.add(`${p}.rows[${i}].direction`, `dirección "${r.direction}" no declarada`);
  }
  for (const [from, to] of Object.entries(mirror)) {
    if (!directions.includes(to)) issues.add(`${p}.mirror.${from}`, `refleja una dirección no dibujada: "${to}"`);
  }
  return { id, image, category, width, height, frame: { width: fw, height: fh }, columns, directions, rowsPerDirection, rows, mirror, origin: { x: ox, y: oy }, glyphs, layer, variant };
}

export function parseSheetCatalog(raw: unknown, source = 'data/art/sheets.json'): SheetCatalog {
  const issues = new Issues();
  const root = issues.record(raw, '$');
  const all = new Map<string, SheetDescriptor>();
  const sheets = root ? issues.record(root['sheets'], '$.sheets') : undefined;
  if (sheets) {
    for (const [id, value] of Object.entries(sheets)) {
      if (!ID_PATTERN.test(id)) {
        issues.add(`$.sheets.${id}`, 'identificador inválido');
        continue;
      }
      const sheet = parseSheet(issues, id, value, `$.sheets.${id}`);
      if (sheet) all.set(id, sheet);
    }
  }
  issues.throwIfAny(source);
  return {
    all,
    get: (id) => {
      const s = all.get(id);
      if (!s) throw new Error(`Hoja desconocida: "${id}"`);
      return s;
    },
    has: (id) => all.has(id),
  };
}

/** Un recurso estático (un solo fotograma) se carga como imagen, no como hoja. */
export function isStaticSheet(sheet: SheetDescriptor): boolean {
  return sheet.columns === 1 && sheet.rows.length === 1 && sheet.rows[0]?.frames === 1;
}

/** Fila que corresponde a una animación y una dirección dibujada (o la única dirección de la hoja). */
export function findRow(sheet: SheetDescriptor, animation: string, direction: string): SheetRow | null {
  return (
    sheet.rows.find((r) => r.animation === animation && r.direction === direction) ??
    (sheet.directions.length <= 1 ? (sheet.rows.find((r) => r.animation === animation) ?? null) : null)
  );
}

export function hasAnimation(sheet: SheetDescriptor, animation: string): boolean {
  return sheet.rows.some((r) => r.animation === animation);
}

/**
 * Traduce una orientación del juego (8 sectores) a una dirección dibujada y si hay que reflejarla.
 * Las hojas con una sola dirección (criaturas miran al oeste, jefe al sur) se reflejan cuando la
 * orientación pedida apunta al lado contrario.
 */
export function resolveDirection(sheet: SheetDescriptor, facing: string | null): { readonly direction: string; readonly flipX: boolean } {
  const first = sheet.directions[0] ?? 'none';
  if (facing === null) return { direction: first, flipX: false };
  if (sheet.directions.includes(facing)) return { direction: facing, flipX: false };
  const mirrored = sheet.mirror[facing];
  if (mirrored !== undefined) return { direction: mirrored, flipX: true };
  if (sheet.directions.length === 1) {
    const flipX = (first === 'w' && facing.includes('e')) || (first === 'e' && facing.includes('w'));
    return { direction: first, flipX };
  }
  return { direction: first, flipX: false };
}

export interface ResolvedFrame {
  /** Índice de celda en la hoja (fila absoluta × columnas + fotograma). */
  readonly index: number;
  readonly flipX: boolean;
  readonly row: SheetRow;
  readonly frame: number;
}

/** Fotograma dentro de una fila: cíclico si la animación se repite; se detiene en el último si no. */
export function frameInRow(row: SheetRow, frame: number): number {
  const f = Math.max(0, Math.floor(frame));
  if (row.loop) return f % row.frames;
  return Math.min(f, row.frames - 1);
}

/** Celda de la hoja para una animación, orientación y número de fotograma; null si la hoja no la contiene. */
export function resolveFrame(sheet: SheetDescriptor, animation: string, facing: string | null, frame: number): ResolvedFrame | null {
  const { direction, flipX } = resolveDirection(sheet, facing);
  const row = findRow(sheet, animation, direction);
  if (!row) return null;
  const f = frameInRow(row, frame);
  return { index: row.row * sheet.columns + f, flipX, row, frame: f };
}

/** Número de fotograma transcurrido para una fila tras `elapsed` segundos. */
export function frameAt(row: SheetRow, elapsed: number): number {
  return Math.floor(Math.max(0, elapsed) * row.fps);
}

/** Duración en segundos de una animación no cíclica. */
export function rowDuration(row: SheetRow): number {
  return row.fps > 0 ? row.frames / row.fps : 0;
}

/** Clave de animación en el motor para una fila de una hoja. */
export function animationKey(textureKey: string, animation: string, direction: string): string {
  return `${textureKey}:${animation}:${direction}`;
}
