import Phaser from 'phaser';
import { referencedSheets, type ArtMap, type PlayerAppearance } from '../../core/art/artMap.ts';
import { swapPaletteInPlace, type PaletteCatalog } from '../../core/art/palette.ts';
import { animationKey, isStaticSheet, type SheetCatalog, type SheetDescriptor } from '../../core/art/spriteSheets.ts';
import { itemIconKey } from './itemIcons.ts';
import { tileTextureKey } from './placeholderTextures.ts';

export const REGISTRY_ART = 'art';
/** Carpeta pública con las hojas (relativa a `index.html`, válida también bajo `/5razas/`). */
const ART_PATH = 'art/';
/** Sombra elíptica dibujada por el motor bajo personajes y criaturas (ART_SPEC §2: sin sombra incorporada). */
export const SHADOW_TEXTURE = 'art-shadow';
export const SHADOW_W = 48;
export const SHADOW_H = 16;
/** Fuente de daño (clave en la caché de fuentes de mapa de bits). */
export const DAMAGE_FONT = 'art-font-damage';

/** Textura cargada más su descriptor. */
export interface ArtLayer {
  readonly key: string;
  readonly sheet: SheetDescriptor;
}

/**
 * Arte definitivo del Nivel A: encola la carga de las hojas referenciadas por `content-map.json`,
 * registra sus animaciones y resuelve qué textura usa cada entidad. Si una hoja falta (o falla la
 * descarga), las consultas devuelven null y las vistas vuelven al placeholder correspondiente.
 */
export class ArtAssets {
  readonly sheets: SheetCatalog;
  readonly map: ArtMap;
  readonly palettes: PaletteCatalog;
  private readonly present = new Set<string>();
  private readonly keys = new Map<string, string>();
  private fontReady = false;

  constructor(sheets: SheetCatalog, map: ArtMap, palettes: PaletteCatalog) {
    this.sheets = sheets;
    this.map = map;
    this.palettes = palettes;
    // Tiles e iconos de objetos sustituyen a los placeholders con sus mismas claves (ARCHITECTURE «Renderizado»).
    for (const [tileId, assetId] of Object.entries(map.tiles)) this.keys.set(assetId, tileTextureKey(tileId));
    for (const [itemId, assetId] of Object.entries(map.items)) this.keys.set(assetId, itemIconKey(itemId));
  }

  /** Clave de textura de una hoja. */
  keyFor(assetId: string): string {
    return this.keys.get(assetId) ?? `art-${assetId}`;
  }

  /** Encola todas las hojas referenciadas (imágenes estáticas u hojas de sprites). */
  queue(loader: Phaser.Loader.LoaderPlugin): void {
    for (const id of referencedSheets(this.map)) {
      const s = this.sheets.get(id);
      const url = ART_PATH + s.image;
      if (isStaticSheet(s)) loader.image(this.keyFor(id), url);
      else loader.spritesheet(this.keyFor(id), url, { frameWidth: s.frame.width, frameHeight: s.frame.height });
    }
  }

  /** Tras la carga: anota qué hojas existen, registra animaciones, la fuente de daño y la sombra. */
  finish(scene: Phaser.Scene): void {
    for (const id of referencedSheets(this.map)) {
      const key = this.keyFor(id);
      if (!scene.textures.exists(key)) continue;
      this.present.add(id);
      const s = this.sheets.get(id);
      if (s.category === 'font' || isStaticSheet(s)) continue;
      registerSheetAnimations(scene, key, s);
    }
    const font = this.sheets.get(this.map.font);
    if (this.present.has(this.map.font) && font.glyphs && !scene.cache.bitmapFont.has(DAMAGE_FONT)) {
      scene.cache.bitmapFont.add(
        DAMAGE_FONT,
        Phaser.GameObjects.RetroFont.Parse(scene, {
          image: this.keyFor(this.map.font),
          width: font.frame.width,
          height: font.frame.height,
          chars: font.glyphs.join(''),
          charsPerRow: font.columns,
          'offset.x': 0,
          'offset.y': 0,
          'spacing.x': 0,
          'spacing.y': 0,
          lineSpacing: 0,
        }),
      );
      this.fontReady = true;
    }
    ensureShadowTexture(scene);
  }

  /** Hojas cargadas y referenciadas que faltan (para el gancho de depuración y las pruebas). */
  debug(): { loaded: number; missing: string[] } {
    const missing = [...referencedSheets(this.map)].filter((id) => !this.present.has(id)).sort();
    return { loaded: this.present.size, missing };
  }

  private layer(assetId: string | undefined): ArtLayer | null {
    if (assetId === undefined || !this.present.has(assetId)) return null;
    return { key: this.keyFor(assetId), sheet: this.sheets.get(assetId) };
  }

  private icon(assetId: string | undefined): string | null {
    return assetId !== undefined && this.present.has(assetId) ? this.keyFor(assetId) : null;
  }

  /**
   * Cuerpo base del Guardián. Si el torso equipado tiene paleta propia (conjunto Raíz profunda), devuelve
   * una copia de la hoja con la sustitución exacta de colores, generada una sola vez.
   */
  playerBody(scene: Phaser.Scene, appearance: PlayerAppearance, chestItemId: string | null): ArtLayer | null {
    const base = this.layer(this.map.player[appearance]);
    if (!base) return null;
    const paletteId = chestItemId === null ? undefined : this.map.bodyPalettes[chestItemId];
    if (paletteId === undefined || !this.palettes.has(paletteId)) return base;
    const key = `${base.key}-${paletteId}`;
    if (!scene.textures.exists(key)) swapSheetPalette(scene, base, key, this.palettes.get(paletteId));
    return { key, sheet: base.sheet };
  }

  portrait(appearance: PlayerAppearance): string | null {
    return this.icon(this.map.portraits[appearance]);
  }

  /** Capa de equipo (casco o arma) de un objeto equipado. */
  equipment(itemId: string | null): ArtLayer | null {
    return itemId === null ? null : this.layer(this.map.equipment[itemId]);
  }

  creature(spriteAtlas: string): ArtLayer | null {
    return this.layer(this.map.creatures[spriteAtlas]);
  }

  /** Animación propia de una habilidad de criatura (p. ej. las del jefe); null → `attack`. */
  creatureAnimation(abilityId: string): string | null {
    return this.map.creatureAnimations[abilityId] ?? null;
  }

  obstacle(): ArtLayer | null {
    return this.layer(this.map.obstacle);
  }

  npc(spriteAtlas: string): ArtLayer | null {
    return this.layer(this.map.npcs[spriteAtlas]);
  }

  plant(plantId: string): ArtLayer | null {
    return this.layer(this.map.plants[plantId]);
  }

  vfx(name: string): ArtLayer | null {
    return this.layer(this.map.vfx[name]);
  }

  skillIcon(abilityId: string): string | null {
    return this.icon(this.map.skills[abilityId]);
  }

  statusIcon(statusId: string): string | null {
    return this.icon(this.map.statuses[statusId]);
  }

  elementIcon(elementId: string): string | null {
    return this.icon(this.map.elements[elementId]);
  }

  /** Clave de la fuente de daño si se cargó. */
  font(): string | null {
    return this.fontReady ? DAMAGE_FONT : null;
  }
}

export function artOf(scene: Phaser.Scene): ArtAssets {
  return scene.registry.get(REGISTRY_ART) as ArtAssets;
}

/** Una animación del motor por cada fila de la hoja: `clave:animación:dirección`. */
export function registerSheetAnimations(scene: Phaser.Scene, key: string, sheet: SheetDescriptor): void {
  for (const row of sheet.rows) {
    const animKey = animationKey(key, row.animation, row.direction);
    if (scene.anims.exists(animKey)) continue;
    scene.anims.create({
      key: animKey,
      frames: Array.from({ length: row.frames }, (_, i) => ({ key, frame: row.row * sheet.columns + i })),
      frameRate: row.fps > 0 ? row.fps : 1,
      repeat: row.loop ? -1 : 0,
    });
  }
}

/** Copia una hoja sustituyendo colores exactos (píxel a píxel) y registra sus celdas. */
function swapSheetPalette(scene: Phaser.Scene, base: ArtLayer, key: string, swap: Readonly<Record<string, string>>): void {
  const source = scene.textures.get(base.key).getSourceImage();
  const { width, height, frame, columns } = base.sheet;
  const canvas = scene.textures.createCanvas(key, width, height);
  if (!canvas) throw new Error(`No se pudo crear la textura ${key}`);
  const ctx = canvas.context;
  ctx.drawImage(source as CanvasImageSource, 0, 0);
  const pixels = ctx.getImageData(0, 0, width, height);
  swapPaletteInPlace(pixels.data, swap);
  ctx.putImageData(pixels, 0, 0);
  const rows = height / frame.height;
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < columns; c++) canvas.add(r * columns + c, 0, c * frame.width, r * frame.height, frame.width, frame.height);
  }
  canvas.refresh();
}

/** Sombra elíptica pixelada, translúcida, para colocar bajo cada entidad dibujada sin sombra propia. */
export function ensureShadowTexture(scene: Phaser.Scene): void {
  if (scene.textures.exists(SHADOW_TEXTURE)) return;
  const canvas = scene.textures.createCanvas(SHADOW_TEXTURE, SHADOW_W, SHADOW_H);
  if (!canvas) throw new Error('No se pudo crear la textura de la sombra');
  const ctx = canvas.context;
  const cx = SHADOW_W / 2;
  const cy = SHADOW_H / 2;
  for (let y = 0; y < SHADOW_H; y++) {
    const ny = (y + 0.5 - cy) / cy;
    const half = Math.sqrt(Math.max(0, 1 - ny * ny)) * cx;
    const inner = half * 0.7;
    ctx.fillStyle = 'rgba(0,0,0,0.22)';
    ctx.fillRect(Math.round(cx - half), y, Math.round(half * 2), 1);
    ctx.fillStyle = 'rgba(0,0,0,0.2)';
    ctx.fillRect(Math.round(cx - inner), y, Math.round(inner * 2), 1);
  }
  canvas.refresh();
}
