import Phaser from 'phaser';
import { DEFAULT_APPEARANCE, PLAYER_APPEARANCES, type PlayerAppearance } from '../../core/art/artMap.ts';
import { ROLE_NAMES, type ProfessionEntry } from '../../core/professions/civilizations.ts';
import type { GameContent } from '../content.ts';
import { artOf } from '../rendering/artAssets.ts';
import { activeTheme, fitPanel, themedButton } from '../ui/panel.ts';
import { themeColor, type UiTheme } from '../ui/theme.ts';
import { REGISTRY_CONTENT, SceneKeys } from './keys.ts';

const W = 940;
const H = 600;
const CARD_GAP = 10;
const CIV_CARD_H = 92;
const PROF_CARD_H = 150;
const PROF_KEYS = ['A', 'B', 'C', 'D', 'E'] as const;
const PORTRAIT = 96;
const APPEARANCE_NAMES: Readonly<Record<PlayerAppearance, string>> = { m: 'Guardián', f: 'Guardiana' };

/**
 * Creación de personaje (GAME_DESIGN §4.1): elegir civilización, profesión y apariencia antes de una
 * partida nueva. Teclas 1–5: civilización; A–E: profesión; G: apariencia; Enter: comenzar; Esc: volver al
 * menú. En el vertical slice solo el Guardián del Bosque es jugable; el resto del catálogo oficial se
 * muestra como «en desarrollo».
 */
export class CharacterScene extends Phaser.Scene {
  private content!: GameContent;
  private theme!: UiTheme;
  private layer!: Phaser.GameObjects.Container;
  private civIndex = 3; // Mapuche: la civilización del vertical slice.
  private profIndex = 0;
  private appearance: PlayerAppearance = DEFAULT_APPEARANCE;

  constructor() {
    super(SceneKeys.Character);
  }

  create(): void {
    this.content = this.registry.get(REGISTRY_CONTENT) as GameContent;
    const civs = this.civilizationIds();
    const playableCiv = civs.findIndex((id) => this.content.civilizations.professionsOf(id).some((p) => p.playable));
    this.civIndex = playableCiv >= 0 ? playableCiv : 0;
    this.profIndex = Math.max(0, this.professions().findIndex((p) => p.playable));
    this.layer = this.add.container(0, 0);
    this.cameras.main.setBackgroundColor('#0d0f14');
    this.scale.on('resize', () => { this.render(); }, this);
    const keyboard = this.input.keyboard;
    keyboard?.on('keydown', (e: KeyboardEvent) => { this.onKey(e); });
    this.events.once(Phaser.Scenes.Events.SHUTDOWN, () => {
      this.scale.off('resize', undefined, this);
      keyboard?.removeAllListeners('keydown');
    });
    this.render();
  }

  private civilizationIds(): string[] {
    return [...this.content.civilizations.civilizations.keys()];
  }

  private professions(): ProfessionEntry[] {
    const id = this.civilizationIds()[this.civIndex];
    return id ? this.content.civilizations.professionsOf(id) : [];
  }

  private selected(): ProfessionEntry | undefined {
    return this.professions()[this.profIndex];
  }

  private onKey(e: KeyboardEvent): void {
    const civs = this.civilizationIds();
    if (/^Digit[1-5]$/.test(e.code)) {
      const i = Number(e.code.slice(5)) - 1;
      if (i < civs.length) this.chooseCivilization(i);
    } else if (/^Key[A-E]$/.test(e.code)) {
      this.chooseProfession(e.code.charCodeAt(3) - 65);
    } else if (e.code === 'KeyG') {
      this.chooseAppearance(this.appearance === 'm' ? 'f' : 'm');
    } else if (e.code === 'Enter' || e.code === 'NumpadEnter') {
      this.start();
    } else if (e.code === 'Escape') {
      this.back();
    }
  }

  private chooseCivilization(i: number): void {
    this.civIndex = i;
    this.profIndex = Math.max(0, this.professions().findIndex((p) => p.playable));
    this.render();
  }

  private chooseProfession(i: number): void {
    if (i < 0 || i >= this.professions().length) return;
    this.profIndex = i;
    this.render();
  }

  private chooseAppearance(a: PlayerAppearance): void {
    this.appearance = a;
    this.render();
  }

  private start(): void {
    const prof = this.selected();
    if (!prof?.playable) return;
    this.scene.start(SceneKeys.Game, { save: null, people: prof.civilizationId, appearance: this.appearance });
  }

  private back(): void {
    this.scene.start(SceneKeys.Menu);
  }

  private text(x: number, y: number, s: string, size = 12, color = '#e6e1cf', wrap = 0): Phaser.GameObjects.Text {
    const t = this.add.text(x, y, s, { fontFamily: 'monospace', fontSize: `${size}px`, color: themeColor(this.theme, color), lineSpacing: 3 });
    if (wrap > 0) t.setWordWrapWidth(wrap);
    this.layer.add(t);
    return t;
  }

  private card(x: number, y: number, w: number, h: number, selected: boolean, accent: number, onClick: () => void): void {
    const t = this.theme;
    const r = this.add.rectangle(x, y, w, h, selected ? t.buttonHover : t.slotFill, t.slotAlpha).setOrigin(0).setStrokeStyle(selected ? 2 : 1, selected ? accent : t.slotStroke);
    r.setInteractive({ useHandCursor: true }).on('pointerdown', onClick);
    this.layer.add(r);
    const stripe = this.add.rectangle(x, y, w, 5, accent).setOrigin(0);
    this.layer.add(stripe);
  }

  private render(): void {
    this.theme = activeTheme(this);
    const t = this.theme;
    const { x, y } = fitPanel(this, this.layer, W, H, 0.85);
    const civs = this.civilizationIds();
    const catalog = this.content.civilizations;
    this.text(x + 20, y + 6, 'Crear personaje — civilización y profesión', 16, t.titleBar ? t.titleText : '#e8c872');
    this.text(x + 20, y + 40, 'Cinco civilizaciones, cinco profesiones cada una. Facciones culturales jugables de un universo de ficción; las clases se inspiran en oficios y no son reconstrucciones históricas.', 11, '#7a7f8c', W - 40);

    // Civilizaciones.
    const cardW = (W - 40 - CARD_GAP * (civs.length - 1)) / civs.length;
    const civY = y + 86;
    civs.forEach((id, i) => {
      const civ = catalog.civilization(id);
      const cx = x + 20 + i * (cardW + CARD_GAP);
      const accent = parseInt(civ.colors.primary.slice(1), 16);
      this.card(cx, civY, cardW, CIV_CARD_H, i === this.civIndex, accent, () => { this.chooseCivilization(i); });
      this.text(cx + 8, civY + 10, `${i + 1}`, 10, '#7a7f8c');
      this.text(cx + 8, civY + 24, civ.name, 14, i === this.civIndex ? '#e8c872' : '#e6e1cf');
      this.text(cx + 8, civY + 46, civ.tagline, 10, '#a9a596', cardW - 16);
      const playable = catalog.professionsOf(id).filter((p) => p.playable).length;
      this.text(cx + 8, civY + CIV_CARD_H - 18, playable > 0 ? `${playable} profesión jugable` : 'En desarrollo', 10, playable > 0 ? '#9fe870' : '#7a7f8c');
    });

    // Profesiones de la civilización elegida.
    const civ = catalog.civilization(civs[this.civIndex] ?? civs[0] ?? '');
    const profY = civY + CIV_CARD_H + 24;
    this.text(x + 20, profY - 20, `${civ.name} · ${civ.region}`, 12, '#e8c872');
    const accent = parseInt(civ.colors.secondary.slice(1), 16);
    this.professions().forEach((p, i) => {
      const px = x + 20 + i * (cardW + CARD_GAP);
      this.card(px, profY, cardW, PROF_CARD_H, i === this.profIndex, accent, () => { this.chooseProfession(i); });
      this.text(px + 8, profY + 10, PROF_KEYS[i] ?? '', 10, '#7a7f8c');
      this.text(px + 8, profY + 24, p.name, 12, i === this.profIndex ? '#e8c872' : '#e6e1cf', cardW - 16);
      this.text(px + 8, profY + 60, ROLE_NAMES[p.role], 11, '#c9c3b0');
      this.text(px + 8, profY + 78, `Final: ${p.finalAbility}`, 10, '#a9a596', cardW - 16);
      this.text(px + 8, profY + PROF_CARD_H - 20, p.playable ? 'Jugable' : 'En desarrollo', 10, p.playable ? '#9fe870' : '#7a7f8c');
    });

    // Apariencia: las dos variantes dibujadas del personaje (ART_SPEC §2), con su retrato.
    const sel = this.selected();
    const art = artOf(this);
    const ay = profY + PROF_CARD_H + 22;
    this.text(x + 20, ay - 18, 'Apariencia (G)', 12, '#e8c872');
    PLAYER_APPEARANCES.forEach((a, i) => {
      const px = x + 20 + i * (PORTRAIT + 120);
      const chosen = a === this.appearance;
      this.card(px, ay, PORTRAIT + 110, PORTRAIT + 10, chosen, accent, () => { this.chooseAppearance(a); });
      const portrait = art.portrait(a);
      if (portrait) this.layer.add(this.add.image(px + 5, ay + 7, portrait).setOrigin(0));
      this.text(px + PORTRAIT + 14, ay + 14, APPEARANCE_NAMES[a], 12, chosen ? '#e8c872' : '#e6e1cf');
      this.text(px + PORTRAIT + 14, ay + 34, chosen ? 'Elegida' : 'Clic o G', 10, chosen ? '#9fe870' : '#7a7f8c');
    });

    // Resumen y botones.
    const by = y + H - 60;
    const summary = sel
      ? sel.playable
        ? `${civ.name} · ${sel.name} (${ROLE_NAMES[sel.role]}). Habilidad final: ${sel.finalAbility}.`
        : `${sel.name} llegará en una fase posterior. En el vertical slice solo es jugable el Guardián del Bosque.`
      : '';
    this.text(x + 20, by - 30, summary, 11, sel?.playable ? '#9fe870' : '#ffd84a', W - 40);
    themedButton(this, this.layer, t, x + W - 190, by, 170, 30, () => { this.start(); }, sel?.playable ?? false);
    this.text(x + W - 190 + 85, by + 8, 'Comenzar (Enter)', 12, sel?.playable ? t.text : '#7a7f8c').setOrigin(0.5, 0);
    themedButton(this, this.layer, t, x + 20, by, 150, 30, () => { this.back(); });
    this.text(x + 20 + 75, by + 8, 'Volver (Esc)', 12, t.text).setOrigin(0.5, 0);
    this.text(x + 20, y + H - 22, 'Teclas: 1–5 civilización · A–E profesión · G apariencia', 10, '#7a7f8c');
  }
}
