import type Phaser from 'phaser';
import type { PlayerCharacter } from '../../core/character/playerCharacter.ts';
import { itemIconKey } from '../rendering/itemIcons.ts';
import type { UiTheme } from './theme.ts';

const SLOT = 44;
const GAP = 6;

/** Consumibles rápidos (inferior derecha, GAME_DESIGN §12) con cantidad y recuperación compartida. */
export class QuickSlotsView {
  private readonly g: Phaser.GameObjects.Graphics;
  private readonly icons: Phaser.GameObjects.Image[] = [];
  private readonly counts: Phaser.GameObjects.Text[] = [];
  private readonly keyLabels: Phaser.GameObjects.Text[] = [];
  private readonly hint: Phaser.GameObjects.Text;
  private readonly keys: readonly string[];
  private readonly theme: UiTheme;
  private x = 0;
  private y = 0;
  private visible = true;
  private signature = '';

  constructor(scene: Phaser.Scene, keys: readonly string[], theme: UiTheme) {
    this.keys = keys;
    this.theme = theme;
    this.g = scene.add.graphics();
    const stroke = theme.titleBar ? 0 : 3;
    keys.forEach((k) => {
      this.icons.push(scene.add.image(0, 0, '__MISSING').setVisible(false));
      this.counts.push(scene.add.text(0, 0, '', { fontFamily: 'monospace', fontSize: '11px', color: theme.slotLabel, stroke: '#000', strokeThickness: stroke }).setOrigin(1, 1));
      this.keyLabels.push(scene.add.text(0, 0, k, { fontFamily: 'monospace', fontSize: '10px', color: theme.slotKey, stroke: '#000', strokeThickness: stroke }));
    });
    this.hint = scene.add.text(0, 0, 'I: inventario', { fontFamily: 'monospace', fontSize: '11px', color: theme.hudText, stroke: theme.hudStroke, strokeThickness: theme.hudStrokeThickness }).setOrigin(1, 1);
  }

  setKeyLabels(labels: readonly string[], inventoryKey: string): void {
    this.keyLabels.forEach((t, i) => t.setText(labels[i] ?? ''));
    this.hint.setText(`${inventoryKey}: inventario`);
  }

  /** Oculta las ranuras (en modo táctil se muestran como botones). */
  setVisible(visible: boolean): void {
    this.visible = visible;
    this.g.setVisible(visible);
    this.hint.setVisible(visible);
    for (const t of [...this.counts, ...this.keyLabels]) t.setVisible(visible);
    if (!visible) for (const i of this.icons) i.setVisible(false);
    this.signature = '';
  }

  layout(right: number, bottom: number): void {
    const width = this.keys.length * SLOT + (this.keys.length - 1) * GAP;
    this.x = right - width;
    this.y = bottom - SLOT - 16;
    this.keys.forEach((_, i) => {
      const sx = this.x + i * (SLOT + GAP);
      this.icons[i]?.setPosition(sx + SLOT / 2, this.y + SLOT / 2);
      this.counts[i]?.setPosition(sx + SLOT - 3, this.y + SLOT - 2);
      this.keyLabels[i]?.setPosition(sx + 3, this.y + 2);
    });
    this.hint.setPosition(right, bottom);
  }

  update(character: PlayerCharacter, now: number): void {
    if (!this.visible) return;
    const cd = character.itemCooldownRatio(now);
    const sig = `${Math.ceil(cd * 20)}|${this.x},${this.y}|` + character.quickSlots.map((id) => (id ? `${id}:${character.inventory.count(id)}` : '-')).join(',');
    if (sig === this.signature) return;
    this.signature = sig;
    const t = this.theme;
    const g = this.g.clear();
    this.keys.forEach((_, i) => {
      const sx = this.x + i * (SLOT + GAP);
      const itemId = character.quickSlots[i] ?? null;
      const count = itemId ? character.inventory.count(itemId) : 0;
      g.fillStyle(t.slotFill, t.slotAlpha).fillRoundedRect(sx, this.y, SLOT, SLOT, t.titleBar ? 3 : 5);
      g.lineStyle(2, t.slotStroke, 1).strokeRoundedRect(sx, this.y, SLOT, SLOT, t.titleBar ? 3 : 5);
      const icon = this.icons[i];
      if (itemId && icon) icon.setTexture(itemIconKey(itemId)).setVisible(true).setAlpha(count > 0 ? 1 : 0.3);
      else icon?.setVisible(false);
      this.counts[i]?.setText(itemId ? String(count) : '');
      if (itemId && cd > 0) g.fillStyle(0x000000, t.titleBar ? 0.35 : 0.55).fillRect(sx, this.y + SLOT * (1 - cd), SLOT, SLOT * cd);
    });
  }
}
