import Phaser from 'phaser';
import { animationKey } from '../../core/art/spriteSheets.ts';
import type { HitArea } from '../../core/combat/hitShapes.ts';
import { cellToScreen, type IsoMetrics } from '../../core/math/iso.ts';
import type { Vec2 } from '../../core/math/vector.ts';
import type { ArtAssets } from './artAssets.ts';
import { OVERLAY_DEPTH } from './depth.ts';

/** Colores provisionales por clave de efecto visual (campo `vfx` de las habilidades). */
const VFX_COLORS: Readonly<Record<string, number>> = {
  slash: 0xf2f0e6,
  charge: 0xf2d16b,
  whirl: 0xbfe3a0,
  barrier: 0x7fd3ff,
  tempest: 0x9fe870,
  dodge: 0xffffff,
  'enemy-slash': 0xff5a4a,
  'enemy-dive': 0xff8a3a,
  'boss-root': 0xd9822b,
  'root-burst': 0x8fbf5a,
};
const DEFAULT_COLOR = 0xffffff;
/** Solo los textos numéricos (daño, curación, XP) usan la fuente de daño pixelada. */
const NUMERIC = /^[+\-−]?\d+!?$/;

/** Muestrea el contorno de un área (en celdas) y lo proyecta a pantalla. */
export function areaOutline(area: HitArea, iso: IsoMetrics): Vec2[] {
  const pts: Vec2[] = [];
  const steps = 28;
  switch (area.shape) {
    case 'circle':
      for (let i = 0; i < steps; i++) {
        const a = (i / steps) * Math.PI * 2;
        pts.push({ x: area.center.x + Math.cos(a) * area.radius, y: area.center.y + Math.sin(a) * area.radius });
      }
      break;
    case 'arc': {
      const base = Math.atan2(area.dir.y, area.dir.x);
      pts.push(area.center);
      for (let i = 0; i <= steps; i++) {
        const a = base - area.halfAngle + (i / steps) * area.halfAngle * 2;
        pts.push({ x: area.center.x + Math.cos(a) * area.radius, y: area.center.y + Math.sin(a) * area.radius });
      }
      break;
    }
    case 'line': {
      const { from, dir, length, halfWidth } = area;
      const n = { x: -dir.y * halfWidth, y: dir.x * halfWidth };
      const to = { x: from.x + dir.x * length, y: from.y + dir.y * length };
      pts.push({ x: from.x + n.x, y: from.y + n.y }, { x: to.x + n.x, y: to.y + n.y });
      pts.push({ x: to.x - n.x, y: to.y - n.y }, { x: from.x - n.x, y: from.y - n.y });
      break;
    }
  }
  return pts.map((p) => cellToScreen(p, iso));
}

/** Punto (en celdas) donde se centra el sprite de un efecto, y su escala según el tamaño del área. */
export function areaFocus(area: HitArea): { readonly at: Vec2; readonly scale: number } {
  switch (area.shape) {
    case 'circle':
      return { at: area.center, scale: area.radius >= 1.5 ? 2 : 1 };
    case 'arc':
      return { at: { x: area.center.x + area.dir.x * area.radius * 0.5, y: area.center.y + area.dir.y * area.radius * 0.5 }, scale: area.radius >= 2.5 ? 2 : 1 };
    case 'line':
      return { at: { x: area.from.x + area.dir.x * area.length * 0.5, y: area.from.y + area.dir.y * area.length * 0.5 }, scale: 1 };
  }
}

/** Efectos de combate: áreas de impacto, telegrafías, sprites de efecto y números de daño (con pooling). */
export class CombatEffects {
  private readonly scene: Phaser.Scene;
  private readonly iso: IsoMetrics;
  private readonly art: ArtAssets;
  private readonly textPool: Phaser.GameObjects.Text[] = [];
  private readonly bitmapPool: Phaser.GameObjects.BitmapText[] = [];

  constructor(scene: Phaser.Scene, iso: IsoMetrics, art: ArtAssets) {
    this.scene = scene;
    this.iso = iso;
    this.art = art;
  }

  /**
   * Dibuja un área; `telegraph` la muestra como aviso durante `duration` segundos. Al impactar, si la
   * habilidad tiene hoja de efecto, se reproduce sobre el área y el contorno queda más tenue.
   */
  showArea(area: HitArea, vfx: string, duration: number, telegraph: boolean, colorOverride: string | null = null): void {
    const color = colorOverride ? parseInt(colorOverride.slice(1), 16) : (VFX_COLORS[vfx] ?? DEFAULT_COLOR);
    const sprite = !telegraph && this.art.vfx(vfx) !== null;
    if (sprite) {
      const focus = areaFocus(area);
      this.playVfx(vfx, focus.at, focus.scale, colorOverride ? color : null);
    }
    const g = this.scene.add.graphics().setDepth(telegraph ? 3 : OVERLAY_DEPTH - 2);
    const pts = areaOutline(area, this.iso);
    g.fillStyle(color, telegraph ? 0.18 : sprite ? 0.12 : 0.35).fillPoints(pts, true);
    g.lineStyle(telegraph ? 1 : 2, color, telegraph ? 0.8 : sprite ? 0.5 : 0.9).strokePoints(pts, true);
    this.scene.tweens.add({
      targets: g,
      alpha: telegraph ? { from: 0.6, to: 1 } : 0,
      duration: Math.max(60, duration * 1000),
      onComplete: () => { g.destroy(); },
    });
  }

  /** Reproduce una hoja de efecto (clave del mapa de arte) en una posición de celdas; nada si no hay hoja. */
  playVfx(name: string, at: Vec2, scale = 1, tint: number | null = null): void {
    const layer = this.art.vfx(name);
    if (!layer) return;
    const p = cellToScreen(at, this.iso);
    const { origin, directions } = layer.sheet;
    const s = this.scene.add.sprite(p.x, p.y, layer.key, 0).setOrigin(origin.x, origin.y).setScale(scale).setDepth(OVERLAY_DEPTH - 1);
    if (tint !== null) s.setTint(tint);
    s.once(Phaser.Animations.Events.ANIMATION_COMPLETE, () => { s.destroy(); });
    s.play(animationKey(layer.key, 'play', directions[0] ?? 'none'));
  }

  /** Número flotante de daño o texto breve (p. ej. "Esquiva") en una posición de celdas. */
  floatText(at: Vec2, text: string, color: string, big = false): void {
    const p = cellToScreen(at, this.iso);
    const x = p.x + (Math.random() - 0.5) * 12;
    const y = p.y - 40;
    const font = this.art.font();
    const target = font && NUMERIC.test(text) ? this.bitmapText(font, text.replace('-', '−'), color, big, x, y) : this.plainText(text, color, big, x, y);
    this.scene.tweens.add({
      targets: target,
      y: y - 26,
      alpha: 0,
      duration: 750,
      ease: 'Cubic.easeOut',
      onComplete: () => {
        target.setActive(false).setVisible(false);
        if (target instanceof Phaser.GameObjects.BitmapText) this.bitmapPool.push(target);
        else this.textPool.push(target);
      },
    });
  }

  private bitmapText(font: string, text: string, color: string, big: boolean, x: number, y: number): Phaser.GameObjects.BitmapText {
    const t = this.bitmapPool.pop() ?? this.scene.add.bitmapText(0, 0, font).setOrigin(0.5);
    t.setText(text)
      .setPosition(x, y)
      .setScale(big ? 3 : 2)
      .setTint(parseInt(color.slice(1), 16))
      .setDepth(OVERLAY_DEPTH)
      .setAlpha(1)
      .setActive(true)
      .setVisible(true);
    return t;
  }

  private plainText(text: string, color: string, big: boolean, x: number, y: number): Phaser.GameObjects.Text {
    const t = this.textPool.pop() ?? this.scene.add.text(0, 0, '', { fontFamily: 'monospace' }).setOrigin(0.5);
    t.setText(text)
      .setPosition(x, y)
      .setStyle({ fontFamily: 'monospace', fontSize: big ? '18px' : '13px', color, stroke: '#000', strokeThickness: 3 })
      .setDepth(OVERLAY_DEPTH)
      .setAlpha(1)
      .setActive(true)
      .setVisible(true);
    return t;
  }
}
