import Phaser from 'phaser';
import { REGISTRY_SETTINGS, type UserSettings } from '../input/settings.ts';
import { THEMES, themeColor, type UiTheme } from './theme.ts';

const MARGIN = 8;
/** Por debajo de esta escala se sugiere girar el dispositivo. */
const HINT_SCALE = 0.7;
const HINT_H = 22;
/** Alto de la barra de título de las ventanas (temas con barra). */
export const TITLE_BAR_H = 28;

/** Coordenada Y para centrar verticalmente un texto de `size` px en la barra de título de un panel en `panelTop`. */
export function titleTextY(panelTop: number, size: number): number {
  return Math.round(panelTop + 1 + (TITLE_BAR_H - size * 1.25) / 2);
}

/** Tema de interfaz activo según la configuración del usuario. */
export function activeTheme(scene: Phaser.Scene): UiTheme {
  const settings = scene.registry.get(REGISTRY_SETTINGS) as UserSettings | undefined;
  return THEMES[settings?.uiTheme ?? 'bosque'];
}

/**
 * Prepara el contenedor de una pantalla superpuesta: fondo atenuado y panel centrado de w × h que
 * siempre cabe en el lienzo (el contenedor se escala si hace falta). Con un tema de ventanas con barra de
 * título, dibuja la barra en la parte superior. Devuelve la esquina superior izquierda del panel en
 * coordenadas del contenedor y la escala aplicada.
 */
export function fitPanel(
  scene: Phaser.Scene,
  layer: Phaser.GameObjects.Container,
  w: number,
  h: number,
  dim = 0.55,
): { x: number; y: number; scale: number } {
  const theme = activeTheme(scene);
  layer.removeAll(true);
  const W = scene.scale.width;
  const H = scene.scale.height;
  let s = Math.min(1, (W - 2 * MARGIN) / w, (H - 2 * MARGIN) / h);
  const hint = s < HINT_SCALE;
  if (hint) s = Math.min(1, (W - 2 * MARGIN) / w, (H - 2 * MARGIN - HINT_H) / h);
  layer.setScale(s);
  const vw = W / s;
  const vh = H / s;
  const top = MARGIN + (hint ? HINT_H : 0);
  const x = Math.round((vw - w) / 2);
  const y = Math.max(top, Math.round((vh - h) / 2));
  layer.add(scene.add.rectangle(0, 0, vw, vh, 0x000000, dim).setOrigin(0).setInteractive());
  layer.add(scene.add.rectangle(x, y, w, h, theme.panelFill, theme.panelAlpha).setOrigin(0).setStrokeStyle(2, theme.panelStroke));
  if (theme.titleBar) {
    const bar = scene.add.graphics();
    bar.fillGradientStyle(theme.titleFill, theme.titleFill, theme.titleFillDark, theme.titleFillDark, 1);
    bar.fillRect(x + 1, y + 1, w - 2, TITLE_BAR_H);
    bar.fillStyle(0xffffff, 0.35).fillRect(x + 1, y + 1, w - 2, 1);
    layer.add(bar);
  }
  if (hint) {
    layer.add(
      scene.add
        .text(vw / 2, y - 6, 'Gira el dispositivo para ampliar esta pantalla', { fontFamily: 'monospace', fontSize: `${Math.round(13 / s)}px`, color: '#f2d16b', stroke: '#000', strokeThickness: 3 })
        .setOrigin(0.5, 1),
    );
  }
  return { x, y, scale: s };
}

/** Crea un botón rectangular con los colores del tema y lo añade al contenedor. */
export function themedButton(
  scene: Phaser.Scene,
  layer: Phaser.GameObjects.Container,
  theme: UiTheme,
  x: number,
  y: number,
  w: number,
  h: number,
  onClick: () => void,
  enabled = true,
): Phaser.GameObjects.Rectangle {
  const r = scene.add.rectangle(x, y, w, h, enabled ? theme.buttonFill : theme.panelFill).setOrigin(0).setStrokeStyle(1, enabled ? theme.buttonStroke : theme.muted === '#6a7390' ? 0xb9c0d2 : 0x3a3f4a);
  if (enabled) {
    r.setInteractive({ useHandCursor: true })
      .on('pointerover', () => r.setFillStyle(theme.buttonHover))
      .on('pointerout', () => r.setFillStyle(theme.buttonFill))
      .on('pointerdown', onClick);
  }
  layer.add(r);
  return r;
}

/**
 * Base de las pantallas superpuestas (diálogo, diario, pausa): fondo atenuado, panel centrado,
 * textos y botones. Pausa la simulación mientras está abierta.
 */
export abstract class PanelScene extends Phaser.Scene {
  protected layer!: Phaser.GameObjects.Container;
  protected session!: { paused: boolean };
  protected theme!: UiTheme;
  /** Borde superior del último panel dibujado (para centrar los títulos en su barra). */
  protected panelTop = 0;

  protected open(session: { paused: boolean }): void {
    this.session = session;
    session.paused = true;
    this.layer = this.add.container(0, 0);
    this.scale.on('resize', () => { this.render(); }, this);
    this.events.once(Phaser.Scenes.Events.SHUTDOWN, () => {
      this.scale.off('resize', undefined, this);
      session.paused = false;
    });
  }

  close(): void {
    this.session.paused = false;
    this.scene.stop();
  }

  protected abstract render(): void;

  /** Panel centrado (escalado si no cabe); devuelve su esquina superior izquierda. */
  protected panel(w: number, h: number, dim = 0.55): { x: number; y: number } {
    this.theme = activeTheme(this);
    const r = fitPanel(this, this.layer, w, h, dim);
    this.panelTop = r.y;
    return r;
  }

  /** Texto del panel. Los colores de la paleta histórica se traducen al tema activo. */
  protected text(x: number, y: number, s: string, size = 12, color = '#e6e1cf', wrap = 0): Phaser.GameObjects.Text {
    // El título de la ventana va centrado sobre la barra de título en los temas que la tienen.
    const onTitleBar = this.theme.titleBar && color === '#e8c872' && size >= 14 && y - this.panelTop < TITLE_BAR_H;
    if (onTitleBar) y = titleTextY(this.panelTop, size);
    const t = this.add.text(x, y, s, {
      fontFamily: 'monospace',
      fontSize: `${size}px`,
      color: onTitleBar ? this.theme.titleText : themeColor(this.theme, color),
      lineSpacing: 3,
    });
    if (wrap > 0) t.setWordWrapWidth(wrap);
    this.layer.add(t);
    return t;
  }

  protected button(x: number, y: number, label: string, onClick: () => void, w = 160, h = 26): Phaser.GameObjects.Rectangle {
    const r = themedButton(this, this.layer, this.theme, x, y, w, h, onClick);
    this.text(x + 10, y + (h - 14) / 2, label, 12, this.theme.text);
    return r;
  }
}
