/**
 * Distribución de los controles táctiles (GAME_DESIGN §12, controles táctiles), independiente de Phaser.
 * Coordenadas en píxeles del lienzo. Ver docs/superpowers/specs/2026-10-31-mobile-responsive-design.md.
 */

export interface Circle {
  readonly x: number;
  readonly y: number;
  readonly r: number;
}

export interface Rect {
  readonly x: number;
  readonly y: number;
  readonly w: number;
  readonly h: number;
}

/** Botones de acción del racimo inferior derecho, en orden de dibujo. */
export const TOUCH_ACTION_BUTTONS = ['basic', 'power1', 'power2', 'power3', 'final', 'dodge', 'quick1', 'quick2'] as const;
export type TouchActionButton = (typeof TOUCH_ACTION_BUTTONS)[number];

/** Accesos de la columna derecha. */
export const TOUCH_MENU_BUTTONS = ['inventory', 'alchemy', 'journal', 'map', 'menu'] as const;
export type TouchMenuButton = (typeof TOUCH_MENU_BUTTONS)[number];

export interface TouchLayout {
  /** Base del joystick; la zona de agarre es `grip` veces mayor. */
  readonly joystick: Circle;
  readonly grip: number;
  readonly buttons: Readonly<Record<TouchActionButton, Circle>>;
  readonly menu: Readonly<Record<TouchMenuButton, Rect>>;
  /** Columna en el borde derecho o, si no cabe (apaisado), fila en la parte superior central. */
  readonly menuPlacement: 'column' | 'row';
  /** Marco compacto del personaje. */
  readonly frame: Rect;
  /** true en pantallas estrechas: el marco va en la esquina superior izquierda. */
  readonly compact: boolean;
  /** Borde superior de la banda de controles (joystick, racimo y consumibles); los avisos van por encima. */
  readonly controlsTop: number;
  /** Escala aplicada al racimo de botones. */
  readonly scale: number;
}

export interface TouchLayoutOptions {
  /** Alto ocupado arriba a la derecha (minimapa y sector) que la columna de accesos debe respetar. */
  readonly reserveTop?: number;
}

const MARGIN = 16;
const FRAME_W = 220;
const FRAME_H = 60;
const MENU_SIZE = 40;
const MENU_GAP = 8;
/** Ancho a partir del cual el marco cabe entre el joystick y el racimo. */
export const WIDE_LAYOUT_MIN_WIDTH = 640;

const polar = (c: { x: number; y: number }, r: number, deg: number) => ({
  x: c.x + Math.cos((deg * Math.PI) / 180) * r,
  y: c.y + Math.sin((deg * Math.PI) / 180) * r,
});

export function computeTouchLayout(width: number, height: number, options: TouchLayoutOptions = {}): TouchLayout {
  const reserveTop = options.reserveTop ?? 0;
  // El racimo y el joystick se reducen en pantallas estrechas y crecen en tabletas.
  const scale = Math.min(1.15, Math.max(0.8, (width - 2 * MARGIN) / 393));
  const joyR = Math.round(60 * scale);
  const joystick = { x: MARGIN + joyR, y: height - MARGIN - joyR, r: joyR };

  const basicR = Math.round(40 * scale);
  const smallR = Math.round(26 * scale);
  const basic = { x: width - MARGIN - basicR, y: height - MARGIN - basicR, r: basicR };
  const inner = Math.round(86 * scale);
  const outer = Math.round(150 * scale);
  const c = (p: { x: number; y: number }, r: number): Circle => ({ x: Math.round(p.x), y: Math.round(p.y), r });
  const buttons: Record<TouchActionButton, Circle> = {
    basic,
    power1: c(polar(basic, inner, 180), smallR),
    power2: c(polar(basic, inner, 225), smallR),
    power3: c(polar(basic, inner, 270), smallR),
    dodge: c(polar(basic, outer, 200), smallR),
    final: c(polar(basic, outer, 250), smallR),
    quick1: { x: 0, y: 0, r: 0 },
    quick2: { x: 0, y: 0, r: 0 },
  };
  // Consumibles rápidos: encima del racimo, alineados a la derecha (en vertical).
  const quickR = Math.round(22 * scale);
  const quickAboveY = basic.y - Math.round(195 * scale);

  // Accesos: columna en el borde derecho (bajo el minimapa, sobre los consumibles) o, si no cabe en
  // altura (apaisado), fila superior central junto con los consumibles.
  const menuSize = Math.round(MENU_SIZE * scale);
  const menuLen = TOUCH_MENU_BUTTONS.length * menuSize + (TOUCH_MENU_BUTTONS.length - 1) * MENU_GAP;
  const columnTop = Math.round(Math.max(reserveTop + MENU_GAP, height * 0.42 - menuLen / 2));
  const menuPlacement: 'column' | 'row' = columnTop + menuLen <= quickAboveY - quickR - MENU_GAP ? 'column' : 'row';
  let menuLeft = width - MARGIN - menuSize;
  if (menuPlacement === 'column') {
    buttons.quick2 = { x: width - MARGIN - quickR, y: quickAboveY, r: quickR };
    buttons.quick1 = { x: buttons.quick2.x - quickR * 2 - 8, y: quickAboveY, r: quickR };
  } else {
    const groupW = quickR * 4 + 8 + MENU_GAP + menuLen;
    const left = Math.round((width - groupW) / 2);
    const quickY = MARGIN + Math.round(menuSize / 2);
    buttons.quick1 = { x: left + quickR, y: quickY, r: quickR };
    buttons.quick2 = { x: left + quickR * 3 + 8, y: quickY, r: quickR };
    menuLeft = left + quickR * 4 + 8 + MENU_GAP;
  }
  const menu = Object.fromEntries(
    TOUCH_MENU_BUTTONS.map((id, i) => [
      id,
      menuPlacement === 'column'
        ? { x: menuLeft, y: columnTop + i * (menuSize + MENU_GAP), w: menuSize, h: menuSize }
        : { x: menuLeft + i * (menuSize + MENU_GAP), y: MARGIN, w: menuSize, h: menuSize },
    ]),
  ) as Record<TouchMenuButton, Rect>;

  // Marco del personaje: entre joystick y racimo si hay sitio; si no (vertical), en la esquina superior
  // izquierda, como en escritorio, dejando libre el centro de la pantalla.
  const bandLeft = joystick.x + joystick.r;
  const bandRight = Math.min(buttons.dodge.x - buttons.dodge.r, buttons.power1.x - buttons.power1.r);
  const compact = width < WIDE_LAYOUT_MIN_WIDTH || bandRight - bandLeft < FRAME_W + 2 * MARGIN;
  const quickTop = menuPlacement === 'column' ? buttons.quick1.y - quickR : Infinity;
  const controlsTop = Math.min(joystick.y - joystick.r, buttons.final.y - buttons.final.r, buttons.dodge.y - buttons.dodge.r, quickTop);
  let frame: Rect;
  if (!compact) {
    frame = { x: Math.round((bandLeft + bandRight) / 2 - FRAME_W / 2), y: height - MARGIN - FRAME_H, w: FRAME_W, h: FRAME_H };
  } else {
    // Si los accesos y consumibles ocupan la fila superior (pantalla baja), el marco va justo debajo.
    const top = menuPlacement === 'row' ? MARGIN + menuSize + MENU_GAP : MARGIN;
    frame = { x: MARGIN, y: top, w: Math.min(FRAME_W, width - 2 * MARGIN), h: FRAME_H };
  }
  return { joystick, grip: 1.6, buttons, menu, menuPlacement, frame, compact, controlsTop, scale };
}
