import type Phaser from 'phaser';
import type { AbilityDefinition } from '../../core/combat/abilities.ts';
import type { Combatant } from '../../core/combat/combatant.ts';
import type { ActionSlot } from '../../core/professions/profession.ts';
import type { UiTheme } from './theme.ts';

const SLOT = 52;
const GAP = 8;

export interface ActionBarSlot {
  readonly slot: ActionSlot;
  readonly key: string;
  readonly ability: AbilityDefinition;
}

/** Devuelve la clave del icono de una habilidad, o null para mostrar sus iniciales. */
export type IconLookup = (abilityId: string) => string | null;

/** Barra de acciones: cinco acciones + evasión, con iconos, recarga y energía, en los colores del tema. */
export class ActionBar {
  private readonly g: Phaser.GameObjects.Graphics;
  private readonly slots: readonly ActionBarSlot[];
  private readonly labels: Phaser.GameObjects.Text[] = [];
  private readonly icons: (Phaser.GameObjects.Image | null)[] = [];
  private readonly timers: Phaser.GameObjects.Text[] = [];
  private readonly keys: Phaser.GameObjects.Text[] = [];
  private readonly flashUntil = new Map<ActionSlot, number>();
  private readonly theme: UiTheme;
  private x = 0;
  private y = 0;
  private signature = '';

  constructor(scene: Phaser.Scene, slots: readonly ActionBarSlot[], theme: UiTheme, iconFor: IconLookup = () => null) {
    this.g = scene.add.graphics();
    this.slots = slots;
    this.theme = theme;
    const stroke = theme.titleBar ? 0 : 3;
    for (const s of slots) {
      const icon = iconFor(s.ability.id);
      const short = s.ability.name.split(' ').map((w) => w[0]).join('').slice(0, 3);
      this.icons.push(icon ? scene.add.image(0, 0, icon) : null);
      this.labels.push(scene.add.text(0, 0, short, { fontFamily: 'monospace', fontSize: '15px', color: theme.slotLabel, stroke: '#000', strokeThickness: stroke }).setOrigin(0.5).setVisible(icon === null));
      this.timers.push(scene.add.text(0, 0, '', { fontFamily: 'monospace', fontSize: '14px', color: theme.slotLabel, stroke: '#000', strokeThickness: icon ? 3 : stroke }).setOrigin(0.5));
      this.keys.push(scene.add.text(0, 0, s.key, { fontFamily: 'monospace', fontSize: '10px', color: theme.slotKey, stroke: '#000', strokeThickness: stroke }).setOrigin(0, 0));
    }
  }

  get width(): number {
    return this.slots.length * SLOT + (this.slots.length - 1) * GAP;
  }

  layout(centerX: number, bottom: number): void {
    this.x = centerX - this.width / 2;
    this.y = bottom - SLOT;
    this.slots.forEach((_, i) => {
      const sx = this.x + i * (SLOT + GAP);
      this.labels[i]?.setPosition(sx + SLOT / 2, this.y + SLOT / 2 - 4);
      this.icons[i]?.setPosition(sx + SLOT / 2, this.y + SLOT / 2 + 2);
      this.timers[i]?.setPosition(sx + SLOT / 2, this.y + SLOT / 2 + 12);
      this.keys[i]?.setPosition(sx + 3, this.y + 2);
    });
  }

  setKeyLabels(labels: Readonly<Record<ActionSlot, string>>): void {
    this.slots.forEach((s, i) => this.keys[i]?.setText(labels[s.slot]));
  }

  /** Oculta la barra (en modo táctil la sustituye el racimo de botones). */
  setVisible(visible: boolean): void {
    this.g.setVisible(visible);
    for (const t of [...this.timers, ...this.keys]) t.setVisible(visible);
    this.labels.forEach((t, i) => t.setVisible(visible && this.icons[i] === null));
    for (const img of this.icons) img?.setVisible(visible);
  }

  /** Resalta en rojo una ranura (p. ej. sin energía). */
  flash(slot: ActionSlot, now: number): void {
    this.flashUntil.set(slot, now + 0.35);
  }

  update(player: Combatant, now: number): void {
    // Solo se redibuja si cambian recuperaciones (en décimas), energía disponible, nivel o avisos.
    const sig = this.slots
      .map((s) => `${Math.ceil(player.cooldownRemaining(s.ability.id, now) * 10)}${player.energy < s.ability.energyCost ? 'e' : ''}${(this.flashUntil.get(s.slot) ?? 0) > now ? 'f' : ''}`)
      .join(',') + `|${player.level}|${this.x},${this.y}`;
    if (sig === this.signature) return;
    this.signature = sig;
    const t = this.theme;
    const g = this.g.clear();
    this.slots.forEach((s, i) => {
      const sx = this.x + i * (SLOT + GAP);
      const remaining = player.cooldownRemaining(s.ability.id, now);
      const total = s.ability.category === 'basic' ? s.ability.cooldown / player.stats.attackRate : s.ability.cooldown;
      const noEnergy = player.energy < s.ability.energyCost;
      const locked = player.level < s.ability.unlockLevel;
      const flashing = (this.flashUntil.get(s.slot) ?? 0) > now;
      const radius = t.titleBar ? 3 : 5;

      g.fillStyle(s.slot === 'final' ? t.slotFinalFill : t.slotFill, t.slotAlpha).fillRoundedRect(sx, this.y, SLOT, SLOT, radius);
      if (remaining > 0 && total > 0) {
        g.fillStyle(0x000000, t.titleBar ? 0.35 : 0.6).fillRect(sx, this.y + SLOT * (1 - remaining / total), SLOT, SLOT * (remaining / total));
      }
      if (noEnergy && !locked) g.fillStyle(0x1a3a6a, t.titleBar ? 0.25 : 0.45).fillRoundedRect(sx, this.y, SLOT, SLOT, radius);
      if (locked) g.fillStyle(0x000000, t.titleBar ? 0.3 : 0.7).fillRoundedRect(sx, this.y, SLOT, SLOT, radius);
      g.lineStyle(2, flashing ? 0xff4a3a : s.slot === 'final' ? t.slotFinalStroke : t.slotStroke, 1).strokeRoundedRect(sx, this.y, SLOT, SLOT, radius);
      const timer = remaining > 0.05 && total >= 1 ? remaining.toFixed(remaining < 3 ? 1 : 0) : '';
      this.timers[i]?.setText(locked ? `Nv ${s.ability.unlockLevel}` : timer).setColor(locked ? t.slotKey : t.slotLabel);
      const alpha = locked ? 0.25 : remaining > 0 || noEnergy ? 0.5 : 1;
      this.labels[i]?.setAlpha(alpha);
      this.icons[i]?.setAlpha(alpha);
    });
  }
}
