import { resolveTouchMode } from '../../core/input/touchInput.ts';
import type { UserSettings } from './settings.ts';

/** true si el puntero principal del dispositivo es grueso (pantalla táctil como entrada principal). */
export function coarsePointer(): boolean {
  if (typeof window === 'undefined' || typeof window.matchMedia !== 'function') return false;
  if (window.matchMedia('(pointer: coarse)').matches) return true;
  // Algunos navegadores móviles no informan del puntero: se usa la capacidad táctil sin puntero fino.
  return navigator.maxTouchPoints > 0 && !window.matchMedia('(pointer: fine)').matches;
}

/** Decide si se muestran los controles táctiles según la configuración y el dispositivo. */
export function touchEnabledFor(settings: UserSettings): boolean {
  return resolveTouchMode(settings.touchControls, coarsePointer());
}
