import type Phaser from 'phaser';
import { animationKey, hasAnimation } from '../../core/art/spriteSheets.ts';
import { cellToScreen, type IsoMetrics } from '../../core/math/iso.ts';
import { npcQuestIndicator, type NpcDefinition } from '../../core/narrative/dialogue.ts';
import type { QuestLog } from '../../core/quests/quests.ts';
import type { NpcPlacement } from '../../core/world/worldMap.ts';
import { SHADOW_TEXTURE, type ArtAssets } from '../rendering/artAssets.ts';
import { ENTITY_DEPTH_BIAS, sortedDepth } from '../rendering/depth.ts';
import { PLAYER_ORIGIN_Y } from '../rendering/placeholderTextures.ts';

const TEXT = { fontFamily: 'monospace', stroke: '#000', strokeThickness: 3 } as const;

/** PNJ con su nombre y un indicador de misión: "!" disponible, "?" lista para entregar. */
export class NpcView {
  readonly npcId: string;
  private readonly marker: Phaser.GameObjects.Text;
  private readonly npc: NpcDefinition;
  private readonly sprite: Phaser.GameObjects.Sprite | null;
  private readonly idleKey: string;
  private readonly talkKey: string | null;
  private talking = false;

  constructor(scene: Phaser.Scene, placement: NpcPlacement, npc: NpcDefinition, iso: IsoMetrics, art: ArtAssets) {
    this.npc = npc;
    this.npcId = npc.id;
    const p = cellToScreen(placement.position, iso);
    const depth = sortedDepth(p.y) + ENTITY_DEPTH_BIAS;
    const layer = art.npc(npc.spriteAtlas);
    let top = 50;
    if (layer) {
      const { origin, frame, directions } = layer.sheet;
      const dir = directions[0] ?? 'none';
      this.idleKey = animationKey(layer.key, 'idle', dir);
      this.talkKey = hasAnimation(layer.sheet, 'talk') ? animationKey(layer.key, 'talk', dir) : null;
      this.sprite = scene.add.sprite(p.x, p.y, layer.key, 0).setOrigin(origin.x, origin.y).setDepth(depth);
      this.sprite.play(this.idleKey);
      scene.add.image(p.x, p.y - 1, SHADOW_TEXTURE).setScale(0.75, 0.6).setDepth(depth - 0.05);
      top = frame.height * origin.y + 4;
    } else {
      this.idleKey = '';
      this.talkKey = null;
      this.sprite = null;
      scene.add.image(p.x, p.y, npc.spriteAtlas).setOrigin(0.5, PLAYER_ORIGIN_Y).setDepth(depth);
    }
    scene.add.text(p.x, p.y - top, npc.name, { ...TEXT, fontSize: '11px', color: '#e8c872' }).setOrigin(0.5, 1).setDepth(depth + 0.2);
    this.marker = scene.add.text(p.x, p.y - top - 12, '', { ...TEXT, fontSize: '18px', color: '#ffd84a' }).setOrigin(0.5, 1).setDepth(depth + 0.2);
    scene.tweens.add({ targets: this.marker, y: p.y - top - 16, duration: 600, yoyo: true, repeat: -1 });
  }

  /** `talkingTo`: PNJ con el que se conversa ahora (animación de hablar), o null. */
  sync(quests: QuestLog, talkingTo: string | null): void {
    this.marker.setText(npcQuestIndicator(this.npc, quests) ?? '');
    const talking = talkingTo === this.npcId;
    if (talking === this.talking || !this.sprite) return;
    this.talking = talking;
    if (talking && this.talkKey) this.sprite.play({ key: this.talkKey, repeat: -1 });
    else this.sprite.play(this.idleKey);
  }
}
