import type Phaser from 'phaser';
import type { UiTheme } from './theme.ts';

const MAX_LINES = 6;
const LIFETIME = 4;
const LINE_H = 16;
/** Tamaño del registro tipo chat (tema Clásico). */
export const LOG_W = 320;
export const LOG_H = MAX_LINES * LINE_H + 10;

interface Line {
  readonly text: Phaser.GameObjects.Text;
  readonly until: number;
}

/**
 * Notificaciones relevantes (GAME_DESIGN §12): botín, XP, avisos. Dos presentaciones según el tema:
 * líneas flotantes alineadas a la derecha (Bosque) o un registro tipo chat abajo a la izquierda (Clásico).
 */
export class NotificationFeed {
  private readonly scene: Phaser.Scene;
  private readonly theme: UiTheme;
  private readonly box: Phaser.GameObjects.Graphics;
  private lines: Line[] = [];
  private x = 0;
  private y = 0;
  private mode: 'floating' | 'log';

  constructor(scene: Phaser.Scene, theme: UiTheme) {
    this.scene = scene;
    this.theme = theme;
    this.mode = theme.feed;
    this.box = scene.add.graphics();
  }

  /** Esquina de anclaje: superior derecha (flotante) o inferior izquierda (registro). */
  layout(x: number, y: number, mode: 'floating' | 'log' = this.theme.feed): void {
    this.x = x;
    this.y = y;
    this.mode = mode;
    this.box.clear();
    if (mode === 'log') {
      this.box.fillStyle(this.theme.logFill, 0.58).fillRect(x, y - LOG_H, LOG_W, LOG_H);
      this.box.lineStyle(1, this.theme.panelStroke, 0.8).strokeRect(x, y - LOG_H, LOG_W, LOG_H);
    }
    this.reflow();
  }

  push(message: string, color: string, now: number): void {
    const log = this.mode === 'log';
    const text = this.scene.add
      .text(0, 0, message, {
        fontFamily: 'monospace',
        fontSize: '12px',
        color: log ? this.theme.logText : color,
        stroke: '#000',
        strokeThickness: log ? 0 : 3,
      })
      .setOrigin(log ? 0 : 1, 0);
    if (log) text.setMaxLines(1).setWordWrapWidth(LOG_W - 12);
    this.lines.unshift({ text, until: now + (log ? LIFETIME * 3 : LIFETIME) });
    while (this.lines.length > MAX_LINES) this.lines.pop()?.text.destroy();
    this.reflow();
  }

  update(now: number): void {
    const before = this.lines.length;
    this.lines = this.lines.filter((l) => {
      const left = l.until - now;
      if (left <= 0) {
        l.text.destroy();
        return false;
      }
      l.text.setAlpha(Math.min(1, left));
      return true;
    });
    if (this.lines.length !== before) this.reflow();
  }

  private reflow(): void {
    if (this.mode === 'log') {
      // La línea más reciente abajo, como un chat.
      this.lines.forEach((l, i) => l.text.setPosition(this.x + 6, this.y - 5 - (i + 1) * LINE_H));
      return;
    }
    this.lines.forEach((l, i) => l.text.setPosition(this.x, this.y + i * LINE_H));
  }
}
